 add('/teacher/courses/'+c.id+'/members/new','Tilføj elev · '+c.name,'Undervisereditorer',()=>`${title('Tilføj elev manuelt',c.name)}${form('member','Elevoplysninger',[{name:'name',label:'Visningsnavn',required:true},{name:'sub',label:'Auth-brugerreference'}],'/teacher/courses/'+c.id+'/members','Tilføj demoelev')}`,'teacher-courses');
