add('/teacher/reviews','Vurderingskø','Underviser',()=>`${title('Venter på din vurdering.','Åbn en aflevering, læs indholdet, og giv privat feedback.')}${row('Alex Jensen · Indledende GDD','Game Design · Scope og første spilbare version','/teacher/submissions/example',state.approved?'Godkendt i demoen':'Afventer vurdering','inbox')}`,'teacher-reviews');
add('/teacher/submissions/example','Vurdér en aflevering','Underviservurdering',()=>`${title('Alex Jensen · GDD til eget spil','Game Design · Privat underviserfeedback')}<div class="cols"><section class="article"><h2>Elevens oplæg</h2><p>En lille 2D-bane med rutevalg, tre runer og en låst portal. Første version skal gøre core loopet afprøveligt.</p>${form('review','Din feedback',[{name:'body',label:'Privat feedback til eleven',type:'textarea',value:'Dit core loop er tydeligt. Afgræns første version til én bane.',required:true}],'/teacher/submissions/example','Gem feedback i demoen')}<div class="actions"><button type="button" class="action" data-action="approve">${state.approved?'Godkendt i demoen ✓':'Godkend aflevering i demoen'}</button>${A('/submissions/example','Se elevens visning','secondary')}</div></section><aside class="aside"><section class="panel"><h2>Kriterier</h2><ul class="goals"><li>En afgrænset første version.</li><li>Forståeligt core loop og regler.</li><li>En plan, der kan afprøves.</li></ul><p>${pill(state.approved?'Godkendt':'Afventer',state.approved?'green':'')}</p></section></aside></div>`,'teacher-reviews');
add('/teacher/students','Elevoversigt','Underviser',()=>`${title('Dine elever','Faglig status og opfølgning. Kun fiktive data i denne prototype.')}${row('Alex Jensen','H3 · Game Design','/teacher/students/alex','Demoprofil','user')}`,'teacher-students');
for(const [suffix,label]of[['','Overblik'],['/activity','Aktivitet'],['/journal','Logbog'],['/badges','Badges']])add('/teacher/students/alex'+suffix,'Alex · '+label,'Elevprofiler',()=>`${title('Alex Jensen',label+' · Underviservisning · Fiktiv elev')}${nav([['Overblik','/teacher/students/alex'],['Aktivitet','/teacher/students/alex/activity'],['Logbog','/teacher/students/alex/journal'],['Badges','/teacher/students/alex/badges']])}${suffix==='/journal'?row('Fra sensor til besked','Synlig for elevens undervisere.','/journal/example','','notebook-pen'):suffix==='/badges'?grid(badges.slice(0,4).map(b=>tile('/badges/'+b.id,b.name,b.desc,v2BadgeStatus(b)))):suffix==='/activity'?row('Arbejdede med MQTT','Eksempel på faglig aktivitet.','/courses/h3/subjects/iot/modules/mqtt','','radio-tower'):`<section class="panel"><h2>Faglig opfølgning</h2><p>Eleven arbejder med H3 og Game Design. Der er et GDD til vurdering og en refleksion i logbogen.</p>${A('/teacher/submissions/example','Åbn afleveringen','action')}</section>`}`,'teacher-students');
