function lessonEditor(m=null){return `${title(m?'Redigér lektion i '+m.name:'Opret en lektion','Indholdet skal være læsbart på sin egen side.')}${form('lesson','Undervisningsmateriale',[{name:'title',label:'Titel',value:m?.lesson||'',required:true},{name:'body',label:'Forklaring og eksempler',type:'textarea',value:m?.desc||'',required:true},{name:'source',label:'Supplerende kildelink',type:'url',value:m?.original||''}],'/teacher/content','Gem lektion i demoen')}`;}
