add('/teacher/badges','Badgekrav og tildeling','Underviser',()=>`${title('Badges med tydelige kriterier.','Definér emne, niveau og det, eleven skal demonstrere.')}<div class="cols"><section class="panel"><h2>Tildel et badge i demoen</h2><form data-form="award" data-next="/teacher/badges"><label class="field">Elev<select name="student"><option>Alex Jensen (demoelev)</option></select></label><label class="field">Badge<select name="badge">${badges.map(b=>`<option value="${b.id}">${E(b.name)} · ${b.id==='friday'?'Særligt badge':'Lille'}</option>`).join('')}</select></label><label class="field">Grundlag<textarea name="body" required placeholder="Hvad har eleven demonstreret? …"></textarea></label><button class="action" type="button" data-action="save-form">Tildel i demoen</button></form><div class="headrow"><h2>Kriterier og niveauer</h2></div>${badges.map(b=>row(b.name,b.desc,'/badges/'+b.id,v2BadgeStatus(b),'award')).join('')}</section><aside class="aside"><section class="panel"><h2>Fem emneniveauer</h2><p>Forklar → klasseprojekt → eget projekt → fremlæg for klassen → undervis andre.</p><p>Særlige fællesskabsbadges bruger deres egne kriterier.</p>${A('/badges','Se elevens badgeside')}</section></aside></div>`,'teacher-content');
function onboarding(c=null){return `${title('Velkomst og onboarding',c?.name||'Konfigurerbar start uden at låse eleven ude.')}${form('onboarding','Velkomsten',[{name:'title',label:'Overskrift',value:'Velkommen til '+(c?.name||'dit forløb'),required:true},{name:'body',label:'Praktiske rammer og første skridt',type:'textarea',required:true}],c?'/teacher/courses/'+c.id:'/teacher/content','Gem velkomst i demoen')}`;}
add('/teacher/onboarding','Konfigurér onboarding','Undervisereditorer',()=>onboarding(),'teacher-content');
add('/teacher/projects','Holdets projekter','Underviser',()=>projectList(false),'teacher-projects');
add('/onboarding','Elevens velkomst','System',()=>`${title('Velkommen til dit forløb.','Find faget, åbn første emne, og se hvad du skal arbejde med.')}<section class="panel"><h2>En enkel start</h2><ol class="goals"><li>Find dit forløb under Fag & forløb.</li><li>Læs læringsmål og dagens materialer.</li><li>Brug quests til krav og afleveringer.</li></ol><div class="actions">${A('/courses','Find dit forløb','action')}${A('/student','Spring velkomsten over','secondary')}</div></section>`,'home');
add('/games','Spilside · Senere udvidelse','Senere',()=>`${title('Holdets spil','Et forslag til en senere arcade.')}<div class="callout">Spilside og highscores er nice-to-have i projektplanen. Her kan du se en sideskabelon uden at forveksle den med de aftalte kernefunktioner.</div>${row('Rune Run · Spilside','Plads til et godkendt browser-build og spilinformation.','/games/rune','','gamepad-2')}`,'explore');
add('/games/rune','Spil og highscores · Senere','Senere',()=>`${title('Rune Run','Skabelon til en senere spilleside.')}<section class="hero"><div><h2>Plads til at spille.</h2><p>Et indlejret build og eventuelle highscores kræver senere afklaring. Se projektets showcase i prototypen.</p>${A('/projects/rune','Se projektet','action')}</div>${scene()}</section>`,'explore');
add('/sources','Kilder og designgrundlag','Fælles',()=>`${title('Kilder til prototypen','Undervisningsindhold er sammenfattet; sider og elevprogression er designforslag.')}<article class="article"><h2>H3 · 2026</h2><p>Ni uger: Arduino, mere Arduino, serverside, mere serverside, projektuge, test og sikkerhed, MVP, projektuge og eksamen. Den konkrete plan kunne læses i browseren.</p>${ext(source.h3,'Åbn H3-planen')}<h2 style="margin-top:25px">Game design fra bunden</h2><p>Syv Rune Run-guider før eget spil, et godkendt GDD og en afleveringsplan med Main, Side og Daily. Øvelser bliver ikke automatisk ekstra afleveringer.</p>${ext(source.game,'Åbn Game Design')}, ${ext('https://app.notion.com/p/3df123f464aa81e9b4e0ec12debd733a','afleveringsplanen')}<h2 style="margin-top:25px">LUP</h2><p>H1–H6, varigheder og faglige mål er sammenfattet fra den lokale undervisningsplan. Koblinger fra mål til emner og badges er forslag, uden påståede formelle målpindekoder.</p>${ext(source.lup,'Åbn LUP')}<h2 style="margin-top:25px">Badgegrundlag</h2><p>Repoets noter beskriver fem emneniveauer og aggregeret statistik. Navne, tildelinger, XP, procenttal og elevprofiler i denne prototype er eksempler.</p><h2 style="margin-top:25px">Forløb, fag og emner</h2><p>De konkrete H3-kilder viser behovet for et ekstra fagniveau under et skoleforløb. Navigationen afprøver dette hierarki; den eksisterende datamodel i appen er ikke ændret.</p></article>`,'profile');
for(const k of questData)add('/submissions/'+k.id,'Din indsendelse · '+k.name,'Afleveringsdetaljer',()=>{
 const values=state.forms['submit-'+k.id],has=!!values;
 return `${title(k.name,'Din indsendelse · Privat feedback · Demo',[['Afleveringer','/submissions'],[k.name]])}<div class="cols"><article class="article"><h2>${has?'Din indsendelse':'Der er endnu ingen indsendelse'}</h2>${has?`<p>${E(values.comment)}</p>${values.link?`<p>${ext(values.link,'Åbn dit indsendte link')}</p>`:''}${values.file?`<p>Valgt fil i demoen: ${E(values.file)}</p>`:''}`:`<p>Læs opgavens krav, og indsend det aftalte indhold gennem afleveringssiden.</p>`}<div class="callout">${has?'Din indsendelse er registreret i prototypen. Afventer en vurdering.':'Denne quest er ikke afleveret i demoen endnu.'}</div><div class="actions">${A('/quests/'+k.id+'/submit',has?'Ret din indsendelse':'Åbn afleveringssiden','action')}${A('/quests/'+k.id,'Se questbeskrivelsen','secondary')}</div></article><aside class="aside"><section class="panel"><h2>Status og adgang</h2><p>${pill(has?'Afleveret i demoen':'Ikke afleveret')}</p><p>Privat feedback vises her, når underviseren har vurderet indholdet.</p><p class="tiny">Der er ingen rigtig filupload eller aflevering i denne designprototype.</p></section></aside></div>`;
},'submissions');
function registerNotes(){state.notes.forEach((n,i)=>add('/journal/new-note-'+i,n.title||'Ny refleksion','Dine demonoter',()=>`${title(n.title||'Din refleksion','Synlig for dine undervisere · Demo')}<article class="article"><p>${E(n.body)}</p>${A('/journal','Tilbage til logbogen','secondary')}</article>`,'journal'));}
registerNotes();
add('/sitemap','Alle sider','Fælles',()=>sitemapPage(),'profile');
function sitemapPage(term=''){const all=[...routes.entries()].filter(([p,r])=>(r.name+' '+r.group+' '+p).toLowerCase().includes(term.toLowerCase()));const groups=[...new Set(all.map(x=>x[1].group))];return `${title('Alle sider i prototypen.',routes.size+' adresser med elevvisning, underviservisning og undersider.')}<label class="field">Find en side<input id="map-search" type="search" name="map-search" autocomplete="off" placeholder="Fx badges, H3 eller vurdering …"></label><div id="map-results">${mapResults(term)}</div>`;}
function mapResults(term){const all=[...routes.entries()].filter(([p,r])=>(r.name+' '+r.group+' '+p).toLowerCase().includes(term.toLowerCase()));return [...new Set(all.map(x=>x[1].group))].map(g=>`<section class="map-group"><h2>${E(g)}</h2><div class="map-links">${all.filter(x=>x[1].group===g).map(([p,r])=>A(p,r.name)).join('')}</div></section>`).join('')||'<p>Ingen sider matcher søgningen.</p>';}
function render(){const entry=routes.get(route)||routes.get('/not-found');if(route.startsWith('/teacher'))state.role='teacher';else if(route==='/student')state.role='student';const teacher=state.role==='teacher';q('#campus-role').textContent=teacher?'Underviser':'Elev';const navs=teacher?[['Overblik','/teacher','teacher-home'],['Forløb & hold','/teacher/courses','teacher-courses'],['Planlægning','/teacher/planner','teacher-planner'],['Vurderinger','/teacher/reviews','teacher-reviews'],['Elever','/teacher/students','teacher-students'],['Indhold','/teacher/content','teacher-content'],['Projekter','/teacher/projects','teacher-projects']]:[['Overblik','/student','home'],['Fag & forløb','/courses','courses'],['Quests','/quests','quests'],['Afleveringer','/submissions','submissions'],['Logbog','/journal','journal'],['Projekter','/projects/mine','projects'],['Udforsk','/explore','explore'],['Badges','/badges','badges'],['Min udvikling','/progress','progress']];q('#campus-nav').innerHTML=navs.map(([t,p,area])=>`<a href="#${p}"${entry.area===area?' aria-current="page"':''}>${t}</a>`).join('');q('.brand').href=teacher?'#/teacher':'#/student';qa('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.role===state.role)));q('#campus-content').innerHTML=entry.render();q('#campus-notice').innerHTML=state.notice?`<div class="toast"><span>${E(state.notice)}</span><button type="button" data-action="dismiss">Luk</button></div>`:'';if(globalThis.lucide){lucide.createIcons({attrs:{width:18,height:18}});q('.app').classList.add('icons-ready');}}
function go(path,save=true){route=path;try{if(location.hash!=='#'+path)history.pushState(null,'','#'+path);}catch{}render();if(save)remember();root.scrollIntoView({block:'start',behavior:'instant'});}
root.addEventListener('click',event=>{const a=event.target.closest('a[href^="#/"]');if(a&&!event.ctrlKey&&!event.metaKey){event.preventDefault();go(a.getAttribute('href').slice(1));return;}const b=event.target.closest('button');if(!b)return;if(b.dataset.action==='save-form'){const form=b.closest('form');if(form.reportValidity())saveForm(form);return;}if(b.dataset.role){state.role=b.dataset.role;state.notice='';go(state.role==='teacher'?'/teacher':'/student');return;}if(b.dataset.badgeFilter){state.badgeFilter=b.dataset.badgeFilter;render();return;}if(b.dataset.questFilter){state.questFilter=b.dataset.questFilter;render();return;}if(b.dataset.character){state.character=b.dataset.character;state.notice='Karakterens udtryk er ændret i demoen.';render();remember();return;}switch(b.dataset.action){case'complete':if(!state.completed.includes(b.dataset.id))state.completed.push(b.dataset.id);state.notice='Lektionen er markeret som læst i demoen.';break;case'like':state.liked=!state.liked;break;case'approve':state.approved=true;state.notice='Afleveringen er godkendt i demoen. Elevens status er opdateret.';break;case'read-notices':state.noticesRead=true;state.notice='Alle notifikationer er markeret som læst i demoen.';break;case'export-demo':state.showExport=!state.showExport;break;case'dismiss':state.notice='';break;default:return;}render();remember();});
function saveForm(f){const values=Object.fromEntries([...new FormData(f)].map(([k,v])=>[k,typeof v==='string'?v.slice(0,1400):(v.name||'')]));state.forms[f.dataset.form]=values;if(f.dataset.form.startsWith('submit-'))state.submission=true;if(f.dataset.form==='journal-new'){state.notes.push(values);const i=state.notes.length-1;add('/journal/new-note-'+i,values.title||'Ny refleksion','Dine demonoter',()=>`${title(values.title||'Din refleksion','Synlig for dine undervisere · Demo')}<article class="article"><p>${E(values.body)}</p>${A('/journal','Tilbage til logbogen','secondary')}</article>`,'journal');}if(f.dataset.form==='award'){state.badges[values.badge]='earned';}state.notice=f.dataset.form==='deletion'?'Demoanmodningen er registreret lokalt. Ingen rigtig sletteanmodning er sendt.':f.dataset.form==='award'?'Badget er tildelt demoprofilen. Se ændringen på badgesiden.':'Din ændring er gemt i prototypen.';go(f.dataset.next||route);}
root.addEventListener('submit',event=>{event.preventDefault();const form=event.target.closest('form[data-form]');if(form&&form.reportValidity())saveForm(form);});
root.addEventListener('input',event=>{if(event.target.id==='concept-search'){q('#concept-results').innerHTML=conceptRows(event.target.value);if(globalThis.lucide)lucide.createIcons();}if(event.target.id==='map-search')q('#map-results').innerHTML=mapResults(event.target.value);});
window.addEventListener('popstate',()=>{route=location.hash.slice(1)||'/student';render();remember();});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p&&p!==route){route=p;render();remember();}});
window.addEventListener('lup:state',event=>{const restored=event.detail?.globals?.widgetState;if(restored?.modelContent?.page&&routes.has(restored.modelContent.page)&&(restored.modelContent.revision||0)>=stateRevision&&restored.modelContent.page!==route){stateRevision=restored.modelContent.revision||0;route=restored.modelContent.page;render();}});
