state.v2={...v2Defaults,...(state.v2||{})};
const V=state.v2;
V.avatar={...v2Defaults.avatar,...V.avatar};V.ranks={...v2Defaults.ranks,...V.ranks};
const v2Modes={green:'Fuldt fremmøde',blue:'Online fremmøde',yellow:'Arbejde hjemme'};
const v2Fmt=new Intl.DateTimeFormat('da-DK',{day:'numeric',month:'short',timeZone:'UTC'});
const v2DayFmt=new Intl.DateTimeFormat('da-DK',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'});
const v2ISO=d=>d.toISOString().slice(0,10);
function v2Date(offset=0,week=V.week){return new Date(Date.UTC(2026,10,2+week*7+offset));}
function v2Mode(date){return V.attendance[date]||['green','green','blue','green','blue','yellow','yellow'][new Date(date+'T12:00:00Z').getUTCDay()];}
function v2Presence(mode){return `<span class="v2-presence"><span class="v2-dot ${mode}" aria-hidden="true"></span>${v2Modes[mode]}</span>`;}
function v2Legend(){return `<div class="v2-legend">${Object.keys(v2Modes).map(v2Presence).join('')}</div>`;}
function v2Cover(key,cls='v2-cover',alt=''){return `<img src="${VIMAGES[key]}" class="${cls}" alt="${E(alt||({h3:'IoT-værksted med mikrocontroller, sensor og dashboard',game:'Rune Run: runer, rutevalg og en portal',project:'Illustreret spilbane med to ruter og runer'})[key])}" width="1024" height="${key==='project'?576:341}">`;}
function v2CourseNavigation(c){return nav([['Forløbet',cp(c)],['Kalender',cp(c)+'/calendar'],['Fag',cp(c)+'/subjects'],['Quests',cp(c)+'/quests'],['Afleveringer',cp(c)+'/submissions'],['Logbog',cp(c)+'/journal'],['Læringsmål',cp(c)+'/goals']]);}
courseNav=v2CourseNavigation;
scene=()=>v2Cover('project','v2-project-image');
function v2EnsureDay(c,date){const path=cp(c)+'/days/'+date;if(!routes.has(path))add(path,'Dag · '+c.name+' · '+date,'Dagsplaner',()=>v2DayPage(c,date),'courses');return path;}
function v2PlanLinks(c){return `<div class="actions">${A(cp(c)+'/calendar','Se ugekalender','action')}${A('/teacher/planner','Planlæg som underviser','secondary')}</div>`;}
function v2NotionCourse(c){const start=c.id==='h3'?new Date(Date.UTC(2026,9,19)):new Date(Date.UTC(2026,10,2));return `${v2Cover(c.id)}${title(c.name,c.desc,[['Fag & forløb','/courses'],[c.name]])}${v2CourseNavigation(c)}<div class="v2-notion"><aside class="v2-toc"><strong>Indhold</strong>${A(cp(c)+'/subjects','Fag og emner')}${A(cp(c)+'/weeks','Ugeoversigt')}${A(cp(c)+'/calendar','Kalender')}${A(cp(c)+'/goals','Læringsmål')}${A('/resources/gdd','GDD og materialer')}${A('/checkin','Stemningsbarometer')}</aside><article class="v2-document"><p>${c.id==='h3'?'Velkommen til H3. Vi bygger en sammenhængende løsning fra sensor og Arduino til backend, database og dashboard. Forløbet veksler mellem fælles oplæg, mindre projekter og jeres samlede løsning.':'Vi bygger Rune Run sammen, undersøger designbegreber og bruger erfaringerne til dit eget spil. Alt fælles teori kommer før eget projekt. Dit eget GDD skal godkendes, før du begynder udviklingen.'}</p><div class="callout"><strong>Undervisere: ${E(c.teacher)}</strong><p>${c.duration}. Dagene nedenfor viser en redigerbar demoplan inspireret af jeres Notion-forløb.</p></div>${v2Legend()}<h2>Hele forløbet fra top til bund</h2>${c.weeks.map((w,i)=>{const monday=new Date(start.getTime()+i*7*86400000);const relevant=v2WeekModules(c,i);return `<details class="v2-week" ${i===(c.id==='h3'?2:0)?'open':''}><summary>Uge ${i+1} · ${E(w)}</summary><p class="small muted">${c.id==='game'?(i===0?'Fælles teori og Rune Run før eget spil.':'Godkendt eget GDD, projektarbejde og løbende afprøvning.'):'Faglige mål, oplæg og projektarbejde i samme uge.'}</p>${Array.from({length:5},(_,d)=>{const date=v2ISO(new Date(monday.getTime()+d*86400000)),path=v2EnsureDay(c,date);const names=c.id==='game'?['Spillets byggesten','To ruter og valg','Tema, held og præcision','Information og puzzles','Ressourcer, deling og eget GDD']:['Fælles opstart','Teori og afprøvning','Projekt og sparring','Byg og dokumentér','Test og ugens opsamling'];return `<div class="v2-day-row"><strong>${A(path,v2DayFmt.format(new Date(date+'T12:00:00Z'))+' · '+(i===0||c.id==='h3'?names[d]:'Eget projekt'))}</strong><div class="v2-stamp">${v2Presence(v2Mode(date))}<span class="tiny muted">Fagligt fokus og dagens materialer</span></div><p>${c.id==='game'?'Læs dagens begreb, brug det i spillet, og forklar det med dit eget eksempel.':'Gennemgå dagens mål, afprøv en del af løsningen, og saml op i logbogen.'}</p></div>`;}).join('')}<h3 style="font-size:16px;margin-top:14px">Ugens materiale</h3>${relevant.map(m=>row(m.name,m.lesson,m.path,'Emneside','book-open')).join('')}</details>`;}).join('')}<h2>Praktisk og valgfrit</h2><p>${c.id==='game'?'Logbog, test og fremvisning holdes adskilt fra dit GDD. Kun de aftalte quests er afleveringer. Game Design har ikke en særskilt mundtlig eksamen.':'Fremmødeform står på den enkelte dag. Dit projektarbejde skal gøre det muligt at forklare både tekniske valg og det, du lærte undervejs.'}</p>${row('Stemningsbarometer','Start dagen med et kort tjek af klassens stemning.','/checkin','','smile')}${row('Frivillig fordybelse','Find ekstra materialer og side quests.','/explore/modules','','sparkles')}<p>${ext(c.source,'Læs det oprindelige Notion-forløb')}</p></article></div>`;}
function v2DayPage(c,date){const entries=V.slots.filter(s=>s.course===c.id&&s.date===date).sort((a,b)=>a.start.localeCompare(b.start));return `${title(v2DayFmt.format(new Date(date+'T12:00:00Z')),c.name+' · Demoplan',[[c.name,cp(c)],['Dagsplan']])}<div class="v2-stamp">${v2Presence(v2Mode(date))}${A('/checkin','Tag dagens stemning','secondary')}${A(cp(c)+'/calendar','Se i kalenderen','secondary')}</div><div class="cols" style="margin-top:23px"><article class="article"><h2>Start med retningen</h2><p>Læs dagens mål, vælg et konkret næste skridt, og afprøv det i dit projekt. Det vigtigste er at kunne forklare dine valg og observationer.</p><h3>Dagens plan</h3>${entries.length?entries.map(s=>row(s.start+' · '+s.title,s.note,'/schedule/'+s.id,s.kind==='quest'?'Quest':'Undervisning',s.kind==='quest'?'flag':'book-open')).join(''):`<div class="callout">Der er endnu ingen tidsplacerede aktiviteter på denne dag. Åbn ugekalenderen for at planlægge den.</div>`}<h3>Materialer og teori</h3>${v2DayModules(c,date).map(m=>row(m.name,m.desc,m.path,'Materiale','layers')).join('')}</article><aside class="aside"><section class="panel"><h2>Dagens læringsmål</h2><ul class="goals"><li>Forklar dagens faglige fokus.</li><li>Byg og afprøv et konkret eksempel.</li><li>Beskriv en observation og et næste skridt.</li></ul><p class="tiny">Eksempelmål til planlægningen.</p></section><section class="panel"><h2>Rund dagen af</h2>${A('/journal/new','Skriv i logbogen','action')}<p>Synlig for dine undervisere.</p></section></aside></div>`;}
function v2WeekModules(c,i){let ids;if(c.id==='game')ids=i===0?gameModules.map(x=>x[0]):['ide'];else ids=i===0?['arduino','cpp']:i===1?['arduino','mqtt']:i<4?['api','realtime','auth']:i===5?['test']:['scrum','sensor-data','visualisering'];return modules.filter(m=>m.c===c&&ids.includes(m.id));}
function v2DayModules(c,date){const d=new Date(date+'T12:00:00Z'),weekday=(d.getUTCDay()+6)%7;if(c.id==='game'){const week=Math.floor((d.getTime()-Date.UTC(2026,10,2,12))/604800000);const ids=week===0?[['byg'],['valg'],['tema','held'],['puzzle'],['balance','ide']][weekday]||['ide']:['ide'];return modules.filter(m=>m.c===c&&ids.includes(m.id));}const week=Math.floor((d.getTime()-Date.UTC(2026,9,19,12))/604800000);return v2WeekModules(c,week);}
function v2Minute(t){const [h,m]=t.split(':').map(Number);return h*60+m;}
function v2Time(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function v2SlotPath(s){const p='/schedule/'+s.id;if(!routes.has(p))add(p,s.title,'Kalenderaktiviteter',()=>v2SlotPage(s),'calendar');return p;}
function v2SlotPage(s){const c=courseData.find(c=>c.id===s.course);return `${title(s.title,c.name+' · '+v2Fmt.format(new Date(s.date+'T12:00:00Z'))+' · '+s.start+'–'+v2Time(v2Minute(s.start)+Number(s.minutes)),[['Kalender',state.role==='teacher'?'/teacher/planner':'/calendar'],[s.title]])}<div class="v2-stamp">${v2Presence(v2Mode(s.date))}${pill(s.kind==='quest'?'Quest':'Undervisning')}</div><article class="article" style="margin-top:20px"><h2>Det skal vi arbejde med</h2><p>${E(s.note||'Byg, afprøv og forklar dit næste skridt.')}</p><div class="actions">${A(s.quest?'/quests/'+s.quest:s.target||cp(c),s.quest?'Åbn quest':'Åbn fagligt materiale','action')}${A(v2EnsureDay(c,s.date),'Åbn hele dagen','secondary')}${state.role==='teacher'?A('/teacher/planner/edit/'+s.id,'Redigér eller flyt','secondary'):''}</div></article>`;}
function v2EnsureSlot(s){v2SlotPath(s);const p='/teacher/planner/edit/'+s.id;if(!routes.has(p))add(p,'Planlæg · '+s.title,'Kalenderredigering',()=>v2SlotForm(s),'teacher-planner');}
V.slots.forEach(v2EnsureSlot);
function v2Calendar(c=null,teacher=false){const fixedScope=!!c;c=c||courseData.find(x=>x.id===V.calendarCourse)||null;const filtered=V.slots.filter(s=>!c||s.course===c.id);const days=Array.from({length:5},(_,d)=>v2Date(d));return `${title(teacher?'Planlæg undervisning og quests.':'Din uge i Campus.',c?c.name:'H3 og Game Design · Eksempelplan')}${c?v2CourseNavigation(c):''}${!fixedScope?`<label class="field" style="max-width:240px">Vis forløb<select name="calendar-course" data-v2-change="calendar-course"><option value="all" ${V.calendarCourse==='all'?'selected':''}>Alle forløb</option>${courseData.map(x=>`<option value="${x.id}" ${V.calendarCourse===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select></label>`:''}<div class="v2-toolbar"><div class="proto-actions"><button type="button" data-v2="week-prev" aria-label="Forrige uge">‹</button><button type="button" data-v2="week-now">Denne uge</button><button type="button" data-v2="week-next" aria-label="Næste uge">›</button></div><h2>${v2Fmt.format(days[0])} – ${v2Fmt.format(days[4])} ${days[4].getUTCFullYear()}</h2>${teacher?A('/teacher/planner/new','Planlæg aktivitet','action'):A('/courses','Find et forløb','secondary')}</div>${v2Legend()}<div class="${teacher?'v2-planning':''}"><div><div class="v2-calendar"><div class="v2-hours">${[8,9,10,11,12,13,14].map(h=>`<div>${h}.00</div>`).join('')}</div>${days.map(d=>{const date=v2ISO(d),cc=c||courseData[0],daypath=v2EnsureDay(cc,date);const events=filtered.filter(e=>e.date===date).sort((a,b)=>a.start.localeCompare(b.start));return `<section class="v2-cal-col"><div class="v2-cal-head"><strong>${A(daypath,new Intl.DateTimeFormat('da-DK',{weekday:'short',day:'numeric',timeZone:'UTC'}).format(d))}</strong>${v2Presence(v2Mode(date))}</div><div class="v2-cal-body" ${teacher?`data-drop-date="${date}"`:''}>${events.length?events.map(s=>`<a href="#${v2SlotPath(s)}" class="v2-event ${s.kind==='quest'?'quest':''} ${s.minutes<=45?'is-short':''} ${s.minutes<=30?'is-tiny':''}" aria-label="${E(s.title+' · '+s.start+'–'+v2Time(v2Minute(s.start)+Number(s.minutes)))}" data-tooltip="${E(s.title+' · '+s.start+'–'+v2Time(v2Minute(s.start)+Number(s.minutes)))}" style="--event-top:${(v2Minute(s.start)-480)/60*65}px;--event-height:${s.minutes/60*65}px" ${teacher?`draggable="true" data-slot-drag="${s.id}"`:''}><small>${s.start}–${v2Time(v2Minute(s.start)+Number(s.minutes))} · ${s.course==='h3'?'H3':'Game Design'}</small><strong>${E(s.title)}</strong></a>`).join(''):'<p class="tiny muted" style="padding:12px 6px">Ingen aktiviteter</p>'}</div></section>`;}).join('')}</div><p class="v2-calendar-note">${teacher?'Træk en aktivitet til en anden dag og tid, eller åbn den for at redigere med tastatur og formular.':'Åbn en aktivitet for at se dagens materiale eller quest.'} Planen er demodata.</p></div>${teacher?`<aside class="panel"><h2>Quests at planlægge</h2><p class="tiny muted">Vælg en quest, og placér den i kalenderen.</p><div class="v2-backlog">${questData.filter(k=>!c||k.course===c.id).slice(0,4).map(k=>`<div style="padding:10px 0;border-bottom:1px solid var(--rule)">${A('/quests/'+k.id,k.name)}<p class="tiny muted">${k.type} · ${k.course==='h3'?'H3':'Game Design'}</p><button type="button" class="secondary" data-v2="schedule-quest" data-id="${k.id}">Placér i ugeplan</button></div>`).join('')}</div><div class="actions">${A('/teacher/quests/new','Opret ny quest','secondary')}${A('/teacher/quest-library','Se alle quests','secondary')}</div></aside>`:''}</div>`;}
function v2Field(label,name,value='',type='text',required=false){return `<label class="field">${label}<input name="${name}" type="${type}" value="${E(value)}" autocomplete="off" ${required?'required':''}></label>`;}
function v2Select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${E(v)}" ${String(value)===String(v)?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;}
function v2SlotForm(s=null){const pending=questData.find(k=>k.id===V.pendingQuest);return `${title(s?'Redigér aktivitet':'Planlæg en aktivitet','Placér undervisning eller en quest på en dag med et tydeligt fremmødekrav.')}<section class="panel wide"><form data-v2-form="slot" data-id="${s?.id||''}">${v2Field('Titel','title',s?.title||pending?.name||'','text',true)}${v2Select('Forløb','course',courseData.map(c=>[c.id,c.name]),s?.course||pending?.course||'h3')}${v2Field('Dato','date',s?.date||v2ISO(v2Date()),'date',true)}${v2Select('Fremmøde','presence',Object.entries(v2Modes),v2Mode(s?.date||v2ISO(v2Date())))}${v2Field('Start','start',s?.start||'09:00','time',true)}${v2Select('Varighed','minutes',[[30,'30 minutter'],[45,'45 minutter'],[60,'1 time'],[90,'1½ time'],[120,'2 timer']],s?.minutes||60)}${v2Select('Tilknyt quest (valgfrit)','quest',[['','Undervisning uden quest'],...questData.map(k=>[k.id,k.name])],s?.quest||pending?.id||'')}<label class="field">Dagens fokus<textarea name="note" placeholder="Læringsmål, materialer og aftaler …">${E(s?.note||'')}</textarea></label><div class="actions"><button type="button" class="action" data-v2="save-v2">Gem i ugeplanen</button>${s?`<button type="button" class="secondary" data-v2="delete-slot" data-id="${s.id}">Fjern fra planen</button>`:''}</div><p class="tiny muted">Kalenderen viser kl. 08–15. Ændringer sker kun i prototypen.</p></form></section>`;}
function v2QuestEditor(k=null){const d=V.questDraft?.id===(k?.id||'new')?V.questDraft:{};const spec=V.specs[k?.id]||{};const cid=d.course||k?.course||'h3';return `${title(k?'Redigér quest':'Opret en quest','Vælg faglig placering, afleveringskrav og hvornår opgaven skal ligge.')}<section class="panel wide"><form data-v2-form="quest" data-id="${k?.id||'new'}">${v2Field('Titel','name',d.name||k?.name||'','text',true)}${v2Select('Forløb','course',courseData.map(c=>[c.id,c.name]),cid)}${v2Select('Emne','module',modules.filter(m=>m.c.id===cid).map(m=>[m.id,m.s.name+' / '+m.name]),d.module||k?.module)}${v2Select('Type','type',[['Main','Main · Obligatorisk'],['Side','Side · Frivillig'],['Daily','Daily · Tilbagevendende, frivillig']],d.type||k?.type||'Main')}<label class="field">Beskrivelse og krav<textarea name="desc" required placeholder="Hvad skal eleven gøre og vise? …">${E(d.desc||k?.desc||'')}</textarea></label>${v2Select('Afleveringsformat','format',[['link','Link til dokument, kode eller spil'],['file','Fil'],['video','Video-link'],['record','Kort registrering']],d.format||spec.format||'link')}${v2Field('Deadline','deadline',d.deadline||spec.deadline||'','date')}${v2Field('XP ved godkendelse','xp',d.xp||spec.xp||100,'number',true)}<label class="field">Vurderingskriterier<textarea name="criteria" placeholder="Hvad skal være opfyldt? …">${E(d.criteria||spec.criteria||'')}</textarea></label><button type="button" class="action" data-v2="save-v2">Gem quest</button><p class="tiny muted">Du kan derefter placere questen i ugekalenderen. XP er et eksempel, ikke en fastlagt regel.</p></form></section>`;}
function v2QuestPage(k){const c=courseData.find(c=>c.id===k.course),m=modules.find(m=>m.id===k.module),spec=V.specs[k.id]||{};return `${title(k.name,k.type+' quest · '+c.name,[[c.name,cp(c)],['Quests',cp(c)+'/quests'],[k.name]])}<div class="cols"><article class="article"><h2>Din opgave</h2><p>${E(k.desc)}</p><h3>Det skal du vise</h3><p>${E(spec.criteria||'Det aftalte indhold skal kunne åbnes og afprøves af underviseren. Forklar dine vigtigste valg og et næste skridt.')}</p><div class="callout">${k.type==='Main'?'Obligatorisk opgave. Afleveret er ikke det samme som godkendt.':'Frivillig aktivitet. Registrér kun arbejde, du faktisk har udført.'}</div><div class="actions">${A('/quests/'+k.id+'/submit','Åbn din aflevering','action')}${m?A(m.path,'Til emnet','secondary'):''}${state.role==='teacher'?A('/teacher/quests/'+k.id+'/edit','Redigér quest','secondary'):''}</div></article><aside class="aside"><section class="panel"><h2>Rammer</h2><p>${pill(k.type+' quest')}</p><p><strong>Deadline</strong><br>${spec.deadline?E(v2Fmt.format(new Date(spec.deadline+'T12:00:00Z'))):'Aftales af underviseren'}</p><p><strong>Aflevering</strong><br>${({link:'Link',file:'Fil',video:'Video-link',record:'Kort registrering'})[spec.format||'link']}</p><p><strong>XP ved godkendelse</strong><br>${E(spec.xp||100)} XP · Eksempel</p></section></aside></div>`;}
questPage=v2QuestPage;
for(const k of V.customQuests||[]){if(!questData.some(q=>q.id===k.id))questData.push(k);}
function v2RegisterQuest(k){add('/quests/'+k.id,k.name,'Questdetaljer',()=>v2QuestPage(k),'quests');add('/teacher/quests/'+k.id+'/edit','Redigér quest · '+k.name,'Questredigering',()=>v2QuestEditor(k),'teacher-planner');add('/quests/'+k.id+'/submit','Aflevér · '+k.name,'Afleveringssider',()=>{const spec=V.specs[k.id]||{},format=spec.format||'link';return `${title('Din aflevering',k.name)}${form('submit-'+k.id,'Det aftalte format',format==='file'?[{name:'file',label:'Vælg fil til demoafleveringen',type:'file',required:true},{name:'comment',label:'Kort besked',type:'textarea'}]:format==='record'?[{name:'comment',label:'Hvad har du udført?',type:'textarea',required:true}]:[{name:'link',label:format==='video'?'Video-link':'Link til dit arbejde',type:'url',required:true,placeholder:'https://…'},{name:'comment',label:'Kort besked',type:'textarea'}],'/submissions/'+k.id,'Aflevér i demoen',k.desc)}<div class="callout">Afleveringen og feedback er private. Demoen sender ikke filer eller links til en underviser.</div>`;},'submissions');if(!routes.has('/submissions/'+k.id))add('/submissions/'+k.id,'Indsendelse · '+k.name,'Afleveringsdetaljer',()=>`${title(k.name,'Afleveret i demoen')}<section class="panel"><p>${E(state.forms['submit-'+k.id]?.comment||'Indhold registreret i prototypen.')}</p>${A('/quests/'+k.id,'Tilbage til opgaven')}</section>`,'submissions');}
questData.forEach(v2RegisterQuest);

const v2MoreBadges=[
 {id:'hawaii',name:'Hawaii-skjorte',icon:'shirt',topic:'Fællesskab',desc:'Mød op i hawaii-skjorte på den aftalte dag, og få deltagelsen bekræftet af underviseren.',percent:16,type:'Særlig'},
 {id:'api',name:'API Bygger',icon:'cable',topic:'Serverside',desc:'Design, afprøv og forklar et API til en konkret datakilde.',percent:29,module:'api',type:'Emne'},
 {id:'sensor',name:'Sensor til handling',icon:'cpu',topic:'Arduino & IoT',desc:'Læs en sensor, brug målingen og vis en tydelig reaktion.',percent:31,module:'arduino',type:'Emne'},
 {id:'git',name:'Git i praksis',icon:'git-branch',topic:'Samarbejde',desc:'Forklar commits og grene med et konkret eksempel fra dit projekt.',percent:38,module:'scrum',type:'Emne'},
 {id:'scope',name:'Scope Keeper',icon:'target',topic:'Game Design',desc:'Afgræns en første spilbar version og begrund det, du valgte fra.',percent:22,module:'ide',type:'Emne'},
 {id:'team',name:'God sparringsmakker',icon:'users',topic:'Fællesskab',desc:'Giv en konkret, anvendelig observation og et forslag i en fælles afprøvning.',percent:41,module:'valg',type:'Social'},
 {id:'path',name:'Første forløb',icon:'route',topic:'Forløb',desc:'Saml dokumentation for de aftalte afsluttende krav i ét forløb.',percent:19,type:'Forløb'}
];
for(const b of v2MoreBadges)if(!badges.some(x=>x.id===b.id))badges.push(b);
for(const b of badges){b.type=b.type||(b.id==='friday'?'Særlig':'Emne');V.ranks[b.id]=V.ranks[b.id]??(state.badges[b.id]==='earned'?1:0);state.badges[b.id]=V.ranks[b.id]>0?'earned':state.badges[b.id]||'locked';}
medal=function(b){const n=Number(V.ranks[b.id]||0),glyph=b.name.split(/\s+/).map(w=>w[0]).slice(0,2).join('');return `<div class="medal state-${n?'earned':'locked'}" aria-hidden="true"><span class="badge-glyph">${E(glyph)}</span>${icon(b.icon)}<span class="rank-number">${n?(b.type==='Emne'?n:'✓'):'○'}</span></div>`;};
badges.find(b=>b.id==='friday').desc='Deltag i Fancy Friday med passende påklædning, og få det bekræftet af underviseren.';
function v2BadgeStatus(b){const n=Number(V.ranks[b.id]||0);return n?('Opnået'+(b.type==='Emne'?' · '+rankNames[n-1]:'')):'Mangler';}
function v2BadgeList(wall=false){const filter=wall?'Alle':V.badgeFilter||'Alle',category=V.badgeCategory||'Alle typer',owned=badges.filter(b=>V.ranks[b.id]>0);const visible=badges.filter(b=>(!wall||V.ranks[b.id]>0)&&(category==='Alle typer'||b.type===category)&&(filter==='Alle'||filter==='Mine'&&V.ranks[b.id]>0||filter==='Mangler'&&!V.ranks[b.id]||filter==='I gang'&&state.badges[b.id]==='progress'&&!V.ranks[b.id]));return `${title(wall?'Det har du opnået.':'Dine færdigheder. Dine badges.',wall?'Din professionelle væg med opnåede badges og plads til certifikater.':'Se tydeligt, hvad du har, hvad du mangler, og hvordan du kommer videre.')}<div class="stats"><div class="stat"><strong>${owned.length}</strong><span>opnåede badges · Demo</span></div><div class="stat"><strong>${badges.length-owned.length}</strong><span>mangler endnu</span></div><div class="stat"><strong>5</strong><span>niveauer pr. emne</span></div></div><div class="filters">${(wall?[]:['Alle','Mine','Mangler','I gang']).map(t=>`<button class="filter" data-v2="badge-filter" data-value="${t}" aria-pressed="${filter===t}">${t}</button>`).join('')}${A(wall?'/badges':'/progress/badges',wall?'Se hele kataloget':'Min badge- og certifikatvæg','secondary')}</div><label class="field" style="max-width:240px">Kategori<select name="badge-category" data-v2-change="badge-category">${['Alle typer','Emne','Særlig','Social','Forløb'].map(t=>`<option ${category===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="badge-grid">${visible.map(b=>{const n=V.ranks[b.id]||0;return `<a href="#/badges/${b.id}" class="badge-card ${n?'':'not-owned'}">${medal(b)}<h2>${E(b.name)}</h2><p>${E(b.desc)}</p><div class="${n?'v2-owned':'v2-missing'}">${n?'✓':'○'} ${E(v2BadgeStatus(b))}</div>${b.type==='Emne'?`<div class="v2-levels" aria-label="${n} af 5 niveauer opnået">${Array.from({length:5},(_,i)=>`<span class="${i<n?'achieved':''}"></span>`).join('')}</div>`:''}<div class="badge-stat">${b.type} · ${b.percent}% har det · Demotal</div></a>`;}).join('')||'<div class="empty"><h2>Ingen badges i dette udvalg</h2><p>Vælg et andet filter for at se flere.</p></div>'}</div>${wall?'<div class="panel" style="margin-top:20px"><h2>Certifikater</h2><p>Forløbsbeviser kan vises her, når underviseren har tildelt dem. Et emnebadge er ikke automatisk et formelt uddannelsesbevis.</p></div>':'<div class="callout">De fem niveauer er: Lille → Mellem → Stor → Mega → Ultra mega. Særlige badges som Hawaii-skjorte og Fancy Friday bruger deres egne krav.</div>'}`;}
function v2BadgeDetail(b){const n=Number(V.ranks[b.id]||0),m=modules.find(m=>m.id===b.module);return `${title(b.name,b.desc,[['Badges','/badges'],[b.name]])}<div class="cols"><section class="panel"><h2>${b.type==='Emne'?'Din vej gennem emnet':'Det kræver dette badge'}</h2>${b.type==='Emne'?ranks.map((r,i)=>`<div class="v2-rank"><span class="rank-dot ${i<n?'achieved':''}">${i<n?'✓':i+1}</span><div><h3>${rankNames[i]} ${i<n?'· Opnået':i===n?'· Dit næste niveau':'· Ikke opnået'}</h3><p>${E(r)}</p><p class="tiny">${i===0?'Vis forståelsen med et konkret eksempel.':`Forudsætter normalt ${rankNames[i-1]} i samme emne.`}</p></div></div>`).join(''):`<p>${E(b.desc)}</p><div class="callout">Underviseren bekræfter, at kriteriet er opfyldt. Dette badge bruger ikke de fem faglige emneniveauer.</div>`}<div class="actions">${m?A(m.path,'Åbn emnet og materialerne','action'):A('/universe','Se mit univers','action')}${A('/teacher/badges','Se tildelingsmockup','secondary')}</div></section><aside class="aside"><section class="panel" style="text-align:center">${medal(b)}<h2 style="margin-top:16px">${E(v2BadgeStatus(b))}</h2><p>${b.type==='Emne'?n+' af 5 niveauer':'Særligt kriterium'}</p><p>${b.percent}% af aktive brugere · Demotal</p><p class="tiny">Tildelinger og statistik er fiktive eksempler.</p></section><section class="panel"><h2>Næste skridt</h2><p>${n===5?'Du har nået alle emnets niveauer i demoen.':n?'Byg videre, dokumentér dit arbejde, og aftal en demonstration med underviseren.':'Åbn materialet, afprøv et eksempel, og vis din forståelse.'}</p></section></aside></div>`;}
function v2BadgeTeacher(){return `${title('Tildel et badge med et tydeligt grundlag.','Vælg et emne og et niveau, eller et særligt badge uden niveau.')}<div class="cols"><section class="panel"><form data-v2-form="badge">${v2Select('Elev','student',[['alex','Alex Jensen · Demoelev']],'alex')}${v2Select('Badge','badge',badges.map(b=>[b.id,b.name+' · '+b.type]),V.awardBadge||'loop')}${v2Select('Niveau for emnebadge','level',rankNames.map((n,i)=>[i+1,(i+1)+' · '+n]),1)}<label class="field">Dokumentation eller observation<textarea name="evidence" required placeholder="Hvad har eleven demonstreret? …"></textarea></label><button class="action" type="button" data-v2="save-v2">Tildel i demoen</button><p class="tiny muted">Emneniveauer tildeles i rækkefølge. Særlige badges ser bort fra niveauvalget.</p></form></section><aside class="aside"><section class="panel"><h2>Elevens status</h2>${badges.map(b=>`<div class="todo">${A('/badges/'+b.id,b.name)}<p class="tiny muted">${E(v2BadgeStatus(b))}</p></div>`).join('')}</section></aside></div>`;}
function v2Sprite(mini=false){const a=V.avatar,hex=(v,f)=>/^#[0-9a-f]{6}$/i.test(v)?v:f,style=['short','long','cap'].includes(a.style)?a.style:'short';return `<div class="v2-sprite ${style} ${mini?'mini':''}" style="--skin:${hex(a.skin,'#c98d69')};--outfit:${hex(a.outfit,'#2452e8')};--hair:${hex(a.hair,'#42302a')}" aria-hidden="true"><span class="hair"></span><span class="face"></span><span class="arms"></span><span class="torso"></span><span class="legs"></span></div>`;}
function v2AvatarPage(){const choices={skin:[['#edc5a2','Lys'],['#c98d69','Mellem'],['#8d5e44','Brun'],['#553b33','Mørk']],outfit:[['#2452e8','Blå'],['#30826a','Grøn'],['#b66291','Rosa'],['#d47837','Orange']],hair:[['#42302a','Mørk'],['#a76636','Brun'],['#d5ac62','Lys'],['#545ca0','Lilla']]};return `${title('Din avatar. Også når du spiller.','Vælg et 2D-udtryk, og brug den samme figur i prøvespillet og dit personlige univers.')}<div class="cols"><section class="panel"><div class="v2-avatar-stage" role="img" aria-label="Din valgte spilavatar">${v2Sprite()}</div><div class="actions">${A('/games/avatar-demo','Prøv din avatar i et spil','action')}${A('/apartment','Til din lejlighed','secondary')}</div><p class="tiny muted">Dette er en mockup af en fælles 2D-avatar. Egentlige spilintegrationer kan bruge samme avatarprofil.</p></section><aside class="aside"><section class="panel"><h2>Dit udtryk</h2>${Object.entries(choices).map(([key,values])=>`<strong class="small">${({skin:'Hudtone',outfit:'Tøjfarve',hair:'Hårfarve'})[key]}</strong><div class="v2-options">${values.map(([color,name])=>`<button class="v2-swatch" style="--swatch:${color}" data-v2="avatar-color" data-key="${key}" data-value="${color}" aria-label="${name}" aria-pressed="${V.avatar[key]===color}"></button>`).join('')}</div>`).join('')}<strong class="small">Hår og tilbehør</strong><div class="v2-options">${[['short','Kort hår'],['long','Langt hår'],['cap','Kasket']].map(([key,name])=>`<button class="filter" data-v2="avatar-style" data-value="${key}" aria-pressed="${V.avatar.style===key}">${name}</button>`).join('')}</div></section></aside></div>`;}
const v2Walls=[10,11,12,18,26,27,35],v2Runes=[5,20,37];
function v2AvatarGame(){const g=V.game,won=g.collected.length===3&&g.player===7;return `${title('Din avatar i Rune Run Mini','En lille 2D-test: saml tre runer, og find portalen.')}<div class="cols"><section class="panel"><h2>${won?'Du nåede i mål!':'Find en rute gennem banen'}</h2><div class="v2-gamegrid" role="img" aria-label="Spilbane med din avatar, tre runer og en portal">${Array.from({length:48},(_,i)=>`<div class="v2-gamecell ${v2Walls.includes(i)?'wall':''}">${g.player===i?v2Sprite(true):i===7?'◎':v2Runes.includes(i)&&!g.collected.includes(i)?'✦':''}</div>`).join('')}</div><div class="v2-controls" aria-label="Flyt avataren"><button style="grid-column:2" data-v2="move-avatar" data-dir="up" aria-label="Op">↑</button><button style="grid-column:1;grid-row:2" data-v2="move-avatar" data-dir="left" aria-label="Venstre">←</button><button style="grid-column:2;grid-row:2" data-v2="move-avatar" data-dir="down" aria-label="Ned">↓</button><button style="grid-column:3;grid-row:2" data-v2="move-avatar" data-dir="right" aria-label="Højre">→</button></div><p class="v2-status" aria-live="polite">${g.collected.length} af 3 runer samlet. ${won?'Godt klaret.':'Brug knapperne eller piletasterne.'}</p></section><aside class="aside"><section class="panel"><h2>Den samme figur</h2><p>Tøj, hår og hudtone følger din avatarprofil.</p><div class="actions">${A('/profile/character','Tilpas avataren','secondary')}<button class="secondary" data-v2="reset-game">Start banen igen</button></div><p class="tiny">Dette er et prøvespil i designprototypen, ikke et spil fra dit rigtige forløb.</p></section></aside></div>`;}
const v2Furniture=[{id:'desk',name:'Skrivebord',level:1},{id:'bed',name:'Seng',level:1},{id:'chair',name:'Stol',level:1},{id:'plant',name:'Plante',level:1},{id:'lamp',name:'Lampe',level:3},{id:'trophy',name:'Trofæ',level:4}];
function v2Furn(id){return `<span class="v2-furniture ${id}" aria-hidden="true"></span>`;}
function v2Apartment(){const selected=V.selectedCell!==null?V.room[V.selectedCell]:null;return `${title('Dit eget lille sted.','En 2D-lejlighed med et rum på 8×6 felter. Vælg et møbel i inventaret, og placér det på gulvet.')}<div class="cols"><section class="v2-room-wrap"><div class="v2-room" aria-label="Dit rum, 8 gange 6 felter">${Array.from({length:48},(_,i)=>{const f=v2Furniture.find(f=>f.id===V.room[i]);return `<button type="button" class="v2-room-cell" data-v2="room-cell" data-cell="${i}" aria-label="Række ${Math.floor(i/8)+1}, felt ${i%8+1}${f?', '+f.name:', tomt'}" aria-pressed="${V.selectedCell===i}">${f?v2Furn(f.id):''}</button>`;}).join('')}</div><p class="v2-status" aria-live="polite">${E(V.roomNotice||(V.moving!==null?'Vælg et frit felt at flytte møblet til.':V.selectedItem?'Valgt: '+v2Furniture.find(f=>f.id===V.selectedItem).name+'. Klik på et frit felt.':'Klik på et møbel for at flytte eller fjerne det.'))}</p>${selected?`<div class="actions"><button class="secondary" data-v2="move-furniture">Flyt ${v2Furniture.find(f=>f.id===selected).name.toLowerCase()}</button><button class="secondary" data-v2="remove-furniture">Tilbage til inventar</button></div>`:''}</section><aside class="aside"><section class="panel"><h2>Dit inventar</h2><p class="tiny muted">Seng, bord, stol og plante er startmøbler. Lampe og trofæ er eksempler på level-belønninger.</p><div class="v2-inventory">${v2Furniture.map(item=>{const placed=Object.values(V.room).includes(item.id);return `<button class="v2-item" data-v2="choose-furniture" data-id="${item.id}" aria-pressed="${V.selectedItem===item.id}" ${placed?'disabled':''}>${v2Furn(item.id)}<span>${item.name}<br><span class="muted">${placed?'I rummet':item.level>1?'Level '+item.level+' · Åben':'Ejet'}</span></span></button>`;}).join('')}</div></section><section class="panel"><div class="person">${v2Sprite()}<div><h2>Dit univers</h2><p>Din figur og dine møbler følger dig.</p>${A('/profile/character','Tilpas avatar')}</div></div><p class="tiny">Kun din egen bolig. Ingen besøg eller deling i denne mockup.</p></section></aside></div>`;}
const v2MoodOptions=[['😄','Glad'],['🙂','Klar'],['😐','Midt imellem'],['😴','Træt'],['😟','Presset']];
function v2MoodPage(teacher=false){const counts=[...V.mood.counts];if(V.mood.selection!==null)counts[V.mood.selection]++;const total=counts.reduce((a,b)=>a+b,0);return `${title(teacher?'Hvordan er klassen landet?':'Hvordan har du det i dag?',teacher?'Et kort stemningstjek før undervisningen. Oversigten viser kun samlede svar.':'Tag et øjeblik til at mærke efter. Du kan også vælge at springe over.')}<div class="cols"><section class="panel"><h2>${teacher?'Klassens stemning':'Dit stemningstjek'}</h2>${teacher?`<div class="actions"><button class="action" data-v2="mood-new">Start en ny runde</button><button class="secondary" data-v2="mood-toggle">${V.mood.open?'Luk for svar':'Åbn for svar'}</button><button class="secondary" data-v2="mood-demo">Vis demosvar</button></div>`:`<div class="v2-moods">${v2MoodOptions.map(([emoji,label],i)=>`<button class="v2-mood" data-v2="mood-vote" data-index="${i}" aria-pressed="${V.mood.selection===i}" ${V.mood.open?'':'disabled'}><span aria-hidden="true">${emoji}</span>${label}</button>`).join('')}</div><p class="v2-status" aria-live="polite">${!V.mood.open?'Runden er lukket af underviseren.':V.mood.selection!==null?'Dit svar er registreret i demoen. Du kan ændre det, mens runden er åben.':'Vælg det, der passer bedst lige nu.'}</p>`}<div style="margin-top:22px">${v2MoodOptions.map(([emoji,label],i)=>`<div class="v2-moodbar"><span>${emoji} ${label}</span>${bar(total?counts[i]/total*100:0,label+': '+counts[i]+' svar')}<span>${counts[i]}</span></div>`).join('')}</div><p class="small muted">${total} svar · ${V.mood.open?'Runden er åben':'Runden er lukket'} · Fiktiv klasse</p></section><aside class="aside"><section class="panel"><h2>En fælles start</h2><p>Brug stemningen til at justere dagens opstart: mere ro, en tydelig fælles retning eller lidt ekstra energi.</p><p>Der vises ingen navne i oversigten. Svar er demodata.</p><div class="actions">${A(teacher?'/teacher/planner':'/calendar','Til dagens plan','action')}${A(teacher?'/checkin':'/teacher/checkin',teacher?'Se elevvisningen':'Se klassens mockup','secondary')}</div></section></aside></div>`;}

