function v2MoveAvatar(dir){const g=V.game,delta={up:-8,down:8,left:-1,right:1}[dir],target=g.player+delta;if(target<0||target>=48||Math.abs(target%8-g.player%8)>1||v2Walls.includes(target))return;g.player=target;if(v2Runes.includes(target)&&!g.collected.includes(target))g.collected.push(target);render();remember();}
function v2SlotClash(s){const start=v2Minute(s.start),end=start+Number(s.minutes);return V.slots.some(other=>other.id!==s.id&&other.date===s.date&&start<v2Minute(other.start)+Number(other.minutes)&&end>v2Minute(other.start));}
function v2Save(formElement){if(!formElement.reportValidity())return;const d=Object.fromEntries([...new FormData(formElement)].map(([k,v])=>[k,String(v).slice(0,1000)]));
 if(formElement.dataset.v2Form==='slot'){
  const id=formElement.dataset.id||'slot-'+Date.now();const s={id,course:d.course,date:d.date,start:d.start,minutes:Number(d.minutes),title:d.title,quest:d.quest||undefined,kind:d.quest?'quest':'lesson',note:d.note};
  if(v2Minute(s.start)<480||v2Minute(s.start)+s.minutes>900){state.notice='Vælg en tid mellem kl. 08 og 15.';render();return;}
  if(v2SlotClash(s)){state.notice='Der ligger allerede en aktivitet på dette tidspunkt. Vælg en anden tid.';render();return;}
  const index=V.slots.findIndex(x=>x.id===id);if(index>=0)V.slots[index]=s;else V.slots.push(s);V.attendance[d.date]=d.presence;
  // Ruterne slår aktiviteten op igen, så flytning også vises på detaljesiden.
  add('/schedule/'+s.id,s.title,'Kalenderaktiviteter',()=>v2SlotPage(V.slots.find(x=>x.id===s.id)||s),'calendar');
  add('/teacher/planner/edit/'+s.id,'Redigér · '+s.title,'Kalenderredigering',()=>v2SlotForm(V.slots.find(x=>x.id===s.id)||s),'teacher-planner');
  V.pendingQuest=null;state.notice='Aktiviteten er gemt i demokalenderen.';V.week=Math.floor((new Date(d.date+'T12:00:00Z').getTime()-Date.UTC(2026,10,2,12))/604800000);go('/teacher/planner');return;
 }
 if(formElement.dataset.v2Form==='quest'){
  const id=formElement.dataset.id==='new'?'custom-'+Date.now():formElement.dataset.id;let k=questData.find(x=>x.id===id);const values={id,name:d.name,type:d.type,course:d.course,module:d.module,desc:d.desc};if(k)Object.assign(k,values);else{questData.push(values);V.customQuests.push(values);k=values;}
  V.specs[id]={format:d.format,deadline:d.deadline,xp:Number(d.xp),criteria:d.criteria};V.questDraft=null;v2RegisterQuest(k);state.notice='Questen er gemt. Du kan nu placere den i ugeplanen.';V.pendingQuest=id;go('/teacher/planner/new');return;
 }
 if(formElement.dataset.v2Form==='badge'){
  const badge=badges.find(b=>b.id===d.badge),level=badge.type==='Emne'?Number(d.level):1,current=Number(V.ranks[badge.id]||0);
  if(level>current+1){state.notice='Tildel det forrige niveau i samme emne først.';render();return;}
  V.ranks[badge.id]=Math.max(current,level);state.badges[badge.id]='earned';state.notice=badge.name+' er tildelt i demoen'+(badge.type==='Emne'?' på niveau '+rankNames[level-1]:'')+'.';render();remember();return;
 }
}
const v2BaseRender=render;
render=function(){if(route==='/checkin')state.role='student';v2BaseRender();const teacher=state.role==='teacher',entry=routes.get(route)||routes.get('/not-found');const items=teacher?[
 ['Overblik','/teacher','teacher-home'],['Forløb & hold','/teacher/courses','teacher-courses'],['Planlægning','/teacher/planner','teacher-planner'],['Vurderinger','/teacher/reviews','teacher-reviews'],['Elever','/teacher/students','teacher-students'],['Indhold','/teacher/content','teacher-content'],['Projekter','/teacher/projects','teacher-projects'],['Stemning','/teacher/checkin','teacher-mood']
 ]:[['Overblik','/student','home'],['Forløb','/courses','courses'],['Kalender','/calendar','calendar'],['Quests','/quests','quests'],['Afleveringer','/submissions','submissions'],['Logbog','/journal','journal'],['Projekter','/projects/mine','projects'],['Badges','/badges','badges'],['Mit univers','/universe','universe'],['Udforsk','/explore','explore']];
 q('#campus-nav').innerHTML=items.map(([name,path,area])=>`<a href="#${path}"${entry.area===area?' aria-current="page"':''}>${name}</a>`).join('');
 const account=q('.account a[href="#/profile"]');if(account)account.innerHTML=`<span class="avatar" style="position:relative;overflow:hidden">${v2Sprite(true)}</span>Alex Jensen`;
 if(globalThis.lucide)lucide.createIcons({attrs:{width:18,height:18}});
};
remember=function(){stateRevision++;if(!window.lupState?.setWidgetState)return;const snap=JSON.parse(JSON.stringify(V));snap.questDraft=null;const demoState={role:state.role,badges:state.badges,completed:state.completed,notes:state.notes.slice(-3).map(n=>({...n,title:String(n.title||'').slice(0,120),body:String(n.body||'').slice(0,350)})),submission:state.submission,approved:state.approved,v2:snap};
 const payload={modelContent:{page:route,role:state.role,concept:'Campus v2',revision:stateRevision},privateContent:{demoState}};
 let safety=0;while(new TextEncoder().encode(JSON.stringify(payload)).length>14500&&safety++<100){if(snap.slots.length>11)snap.slots.shift();else if(snap.customQuests.length>1)snap.customQuests.shift();else if(Object.keys(snap.specs).length>2)delete snap.specs[Object.keys(snap.specs)[0]];else{demoState.notes=[];break;}}
 window.lupState.setWidgetState(payload).catch(()=>{});
};
root.addEventListener('click',event=>{const b=event.target.closest('[data-v2]');if(!b)return;const action=b.dataset.v2;
 if(action==='save-v2'){v2Save(b.closest('form'));return;}
 if(action==='week-prev')V.week--;else if(action==='week-next')V.week++;else if(action==='week-now')V.week=0;
 else if(action==='schedule-quest'){V.pendingQuest=b.dataset.id;go('/teacher/planner/new');return;}
 else if(action==='delete-slot'){V.slots=V.slots.filter(s=>s.id!==b.dataset.id);routes.delete('/schedule/'+b.dataset.id);routes.delete('/teacher/planner/edit/'+b.dataset.id);state.notice='Aktiviteten er fjernet fra demoplanen.';go('/teacher/planner');return;}
 else if(action==='badge-filter')V.badgeFilter=b.dataset.value;
 else if(action==='avatar-color')V.avatar[b.dataset.key]=b.dataset.value;
 else if(action==='avatar-style')V.avatar.style=b.dataset.value;
 else if(action==='move-avatar'){v2MoveAvatar(b.dataset.dir);return;}
 else if(action==='reset-game'){V.game={player:40,collected:[]};}
 else if(action==='choose-furniture'){V.selectedItem=b.dataset.id;V.selectedCell=null;V.moving=null;V.roomNotice='';}
 else if(action==='room-cell'){
  const cell=Number(b.dataset.cell);V.roomNotice='';
  if(V.moving!==null){if(V.room[cell]&&cell!==V.moving)V.roomNotice='Feltet er optaget. Vælg et frit felt.';else{const item=V.room[V.moving];delete V.room[V.moving];V.room[cell]=item;V.selectedCell=cell;V.moving=null;V.roomNotice='Møblet er flyttet.';}}
  else if(V.room[cell]){V.selectedCell=cell;V.selectedItem=null;}
  else if(V.selectedItem){if(Object.values(V.room).includes(V.selectedItem))V.roomNotice='Møblet er allerede placeret.';else{V.room[cell]=V.selectedItem;V.selectedCell=cell;V.selectedItem=null;V.roomNotice='Møblet er placeret.';}}
  else{V.selectedCell=cell;V.roomNotice='Vælg et møbel fra inventaret først.';}
 }
 else if(action==='move-furniture'){V.moving=V.selectedCell;V.selectedItem=null;V.roomNotice='Klik på et frit felt at flytte til.';}
 else if(action==='remove-furniture'){delete V.room[V.selectedCell];V.selectedCell=null;V.moving=null;V.roomNotice='Møblet er tilbage i inventaret.';}
 else if(action==='mood-vote'){if(!V.mood.open)return;V.mood.selection=Number(b.dataset.index);}
 else if(action==='mood-new'){V.mood={...V.mood,open:true,selection:null,counts:[0,0,0,0,0]};}
 else if(action==='mood-toggle')V.mood.open=!V.mood.open;
 else if(action==='mood-demo'){V.mood.counts=[3,6,4,2,1];}
 else return;render();remember();
});
root.addEventListener('change',event=>{
 if(event.target.dataset.v2Change==='calendar-course'){V.calendarCourse=event.target.value;render();remember();return;}
 if(event.target.dataset.v2Change==='badge-category'){V.badgeCategory=event.target.value;render();remember();}
 const f=event.target.closest('form[data-v2-form="quest"]');if(f&&event.target.name==='course'){V.questDraft={...Object.fromEntries(new FormData(f)),id:f.dataset.id};V.questDraft.module=modules.find(m=>m.c.id===event.target.value)?.id;render();}
});
window.addEventListener('keydown',event=>{if(route!=='/games/avatar-demo'||['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName))return;const dir={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[event.key];if(dir){event.preventDefault();v2MoveAvatar(dir);}});
root.addEventListener('dragstart',event=>{const slot=event.target.closest('[data-slot-drag]');if(slot&&state.role==='teacher'){event.dataTransfer.setData('text/plain',slot.dataset.slotDrag);event.dataTransfer.effectAllowed='move';}});
root.addEventListener('dragover',event=>{if(state.role==='teacher'&&event.target.closest('[data-drop-date]'))event.preventDefault();});
root.addEventListener('drop',event=>{const target=event.target.closest('[data-drop-date]');if(!target||state.role!=='teacher')return;event.preventDefault();const id=event.dataTransfer.getData('text/plain'),slot=V.slots.find(s=>s.id===id);if(!slot)return;const r=target.getBoundingClientRect(),minutes=480+Math.max(0,Math.round((event.clientY-r.top)/65*2)*30),moved={...slot,date:target.dataset.dropDate,start:v2Time(minutes)};
 if(minutes+Number(slot.minutes)>900||v2SlotClash(moved)){state.notice='Her er der ikke plads til aktiviteten. Åbn den for at vælge en anden tid.';render();return;}
 Object.assign(slot,moved);state.notice='Aktiviteten er flyttet i demoplanen.';render();remember();});

