courseNav=()=>'';subjectNav=()=>'';v2CourseNavigation=()=>'';
const v3PrevCalendar=v2Calendar;
v2Calendar=function(c=null,teacher=false){return v3PrevCalendar(!teacher&&!v3Teacher()?(c||v3Course()):c,teacher);};
function v3EmptyLearning(){return `<section class="v3-empty"><h2>Der er luft mellem forløbene.</h2><p>Du er ikke tilmeldt et aktivt forløb lige nu. Udforsk fag og projekter, og byg videre på din avatar, lejlighed og dine badges.</p><div class="actions">${A('/courses','Se forløb','action')}${A('/explore/modules','Udforsk fag og emner','secondary')}</div></section>`;}
function v3Home(){const c=v3Course();return `<div class="v3-home-top"><div><h1>Godmorgen, Alex.</h1><p>${c?'Din dag i '+E(c.name)+'.':'Dit næste kapitel starter her.'}</p></div></div>${c?`<div class="cols"><div><section class="v3-next"><div class="v3-next-copy">${pill(c.id==='h3'?'Uge 3 · Serverside':'Uge 1 · Rune Run')}<h2>${c.id==='h3'?'Fra sensor til noget, der virker.':'Byg et spil. Forstå valgene.'}</h2><p>${E(c.desc)}</p><div class="actions">${A(cp(c),'Åbn mit forløb','action')}</div><div class="v3-quick-links">${A('/calendar','Min uge')}${A('/quests','Quests og afleveringer')}${A('/journal','Logbog')}</div></div>${v2Cover(c.id,'v3-home-image')}</section><div class="headrow"><h2>Dit næste skridt</h2>${A('/attention','Se det, du mangler')}</div>${v3Pending().map(p=>`<div class="v3-task"><span class="v3-count">!</span><div><h3>${A(p.path,p.title)}</h3><p>${p.desc}</p></div><span class="v3-task-state todo">Mangler</span></div>`).join('')||'<div class="callout">Du er ajour med dagens opfølgning.</div>'}<div class="headrow"><h2>Bliv i dit forløb</h2></div>${row('Fag og emner',c.name,cp(c)+'/subjects','Se indhold','book-open')}${row('Læringsmål','Se hvad du arbejder hen imod.',cp(c)+'/goals','','target')}</div><aside class="aside"><section class="panel"><h2>Din udvikling</h2><div class="v3-wallet-panel"><div><strong>${v3Level()}</strong><span>Level</span></div><div class="v3-gold"><strong>${v3Num(U.gold)}</strong><span>Guld</span></div></div><div class="v3-level-track"><span style="width:${U.xp%200/2}%"></span></div><p>${200-U.xp%200} XP til level ${v3Level()+1}</p>${A('/progress','Se XP og belønninger')}</section><section class="panel"><h2>Dit eget sted</h2><div class="person">${v2Sprite()}<div><p>Tag din figur med i spil, og indret dit rum.</p>${A('/universe','Åbn mit univers')}</div></div></section></aside></div>`:`${v3EmptyLearning()}<div class="headrow"><h2>Dit univers følger dig</h2></div>${grid([tile('/progress','Din udvikling',v3Num(U.xp)+' XP · Level '+v3Level()),tile('/projects/mine','Mine projekter','Dine projekter bliver her mellem forløb.'),tile('/apartment','Min lejlighed','Brug dit guld på møbler, og indret dit rum.'),tile('/badges','Badgekatalog','Se dine badges og dit næste mål.')])}`}`;}
function v3TaskTabs(sub=false,c=null){return `<div class="v3-task-tabs" aria-label="Quests og afleveringer">${A(c?cp(c)+'/quests':'/quests','Quests',sub?'':'v3-current')}${A(c?cp(c)+'/submissions':'/submissions','Mine afleveringer',sub?'v3-current':'')}</div>`;}
function v3Tasks(sub=false,c=null){c=c||v3Course();if(!c&&!v3Teacher())return `${title('Min læring')}${v3EmptyLearning()}`;const items=questData.filter(k=>(!c||k.course===c.id)&&(!sub||U.submissions[k.id]));return `${title(sub?'Mine afleveringer':'Quests og afleveringer',sub?'Dine indsendelser og privat feedback.':'Questen er opgaven. Afleveringen er dit svar på den.')}${v3TaskTabs(sub,c)}${!sub?`<div class="filters">${['Alle','Main','Side','Daily'].map(x=>`<button class="filter" data-quest-filter="${x}" aria-pressed="${(state.questFilter||'Alle')===x}">${x==='Alle'?'Alle quests':x}</button>`).join('')}</div>`:''}${items.filter(k=>sub||!state.questFilter||state.questFilter==='Alle'||k.type===state.questFilter).map(k=>{const s=U.submissions[k.id];return `<div class="v3-task"><div><h3>${A(sub?'/submissions/'+k.id:'/quests/'+k.id,k.name)}</h3><p>${E(sub?(s.comment||'Din indsendelse'):k.desc)}</p><div class="v3-quest-group">${pill(k.type)}<span class="tiny muted">${k.course==='h3'?'H3':'Game Design'}</span></div></div><span class="v3-task-state ${!s?'todo':''}">${s?.status==='approved'?'✓ Godkendt':s?.status==='submitted'?'Afventer vurdering':'Ikke afleveret'}</span></div>`;}).join('')||'<section class="v3-empty"><h2>Ingen afleveringer endnu</h2><p>Åbn en quest, læs kravene, og vælg derefter “Lav aflevering”.</p></section>'}`;}
function v3QuestPage(k){const c=courseData.find(c=>c.id===k.course),m=modules.find(m=>m.id===k.module),spec=V.specs[k.id]||{},s=U.submissions[k.id],allowed=v3Teacher()||U.activeCourse===k.course;return `${title(k.name,k.type+' quest · '+c.name)}<div class="v3-step-strip"><strong>1. Læs questen</strong><span>›</span><span>2. Lav afleveringen</span><span>›</span><span>3. Få feedback</span></div><div class="cols"><article class="article"><h2>Opgaven</h2><p>${E(k.desc)}</p><h3>Det skal du vise</h3><p>${E(spec.criteria||'Vis dit arbejde, forklar dine vigtigste valg, og dokumentér at løsningen kan afprøves.')}</p><div class="v3-reward-line">${icon('sparkles')} ${Number(spec.xp||100)} XP <span>+</span><i class="v3-gold-dot" aria-hidden="true"></i>${Math.round(Number(spec.xp||100)/5)} guld ved godkendelse</div><div class="actions">${allowed?A('/quests/'+k.id+'/submit',s?'Ret din aflevering':'Lav aflevering','action'):'<span class="tiny muted">Aflevering er tilgængelig, når du er aktiv på dette forløb.</span>'}${s?A('/submissions/'+k.id,'Se status og feedback','secondary'):''}${m?A(m.path,'Tilbage til emnet','secondary'):''}${v3Teacher()?A('/teacher/quests/'+k.id+'/edit','Redigér quest','secondary'):''}</div></article><aside class="aside"><section class="panel"><h2>Din aflevering</h2><p>${s?.status==='approved'?'✓ Godkendt':s?'Afventer vurdering':'Ikke afleveret'}</p><p>Afleveringen og feedback er private. Et projekt i galleriet oprettes særskilt.</p><p><strong>Format</strong><br>${({link:'Link',file:'Fil',video:'Video-link',record:'Kort registrering'})[spec.format||'link']}</p><p><strong>Frist</strong><br>${spec.deadline?E(spec.deadline):'Aftales af underviseren'}</p></section></aside></div>`;}
v2QuestPage=v3QuestPage;questPage=v3QuestPage;
function v3Submission(k,teacher=false){const s=U.submissions[k.id],spec=V.specs[k.id]||{};return `${title(teacher?'Vurdér · '+k.name:'Min aflevering · '+k.name,'Privat mellem elev og underviser')}<div class="v3-step-strip">${A('/quests/'+k.id,'1. Questen')}<span>›</span><strong>2. Din aflevering</strong><span>›</span><span>3. Feedback</span></div><div class="cols"><article class="article"><h2>${teacher?'Alex Jensens indsendelse':'Dit indsendte arbejde'}</h2>${s?`<p>${E(s.comment||'Indsendelsen er registreret i demoen.')}</p>${s.link?`<p>${ext(s.link,'Åbn det indsendte link')}</p>`:''}<p>${pill(s.status==='approved'?'Godkendt':'Afventer vurdering',s.status==='approved'?'green':'')}</p>${s.feedback?`<h3>Underviserens feedback</h3><div class="feedback"><p>${E(s.feedback)}</p></div>`:''}`:'<p>Du har ikke afleveret et svar på denne quest endnu.</p>'}${teacher&&s?`<label class="field" style="margin-top:20px">Privat feedback<textarea id="v3-feedback">${E(s.feedback||'')}</textarea></label><div class="actions"><button type="button" class="action" data-v3="approve" data-id="${k.id}" ${s.status==='approved'?'disabled':''}>${s.status==='approved'?'Allerede godkendt':'Godkend og tildel belønning'}</button></div><p class="tiny muted">${Number(spec.xp||100)} XP og ${Math.round(Number(spec.xp||100)/5)} guld tildeles én gang pr. quest.</p>`:`<div class="actions">${A('/quests/'+k.id+'/submit',s?'Ret og aflever igen':'Lav aflevering','action')}${A('/quests/'+k.id,'Se questens krav','secondary')}</div>`}</article><aside class="aside"><section class="panel"><h2>Quest og aflevering</h2><p>Questen beskriver opgaven og kravene. Afleveringen indeholder dit svar, din status og underviserens feedback.</p><p>Et projekt er en selvstændig præsentation af det, du har bygget.</p></section></aside></div>`;}
function v3RegisterSubmissions(k){add('/submissions/'+k.id,'Min aflevering · '+k.name,'Afleveringer',()=>v3Submission(k),'submissions');add('/teacher/submissions/'+k.id,'Vurdér · '+k.name,'Vurderinger',()=>v3Submission(k,true),'teacher-reviews');}
questData.forEach(v3RegisterSubmissions);
const v3OldRegisterQuest=v2RegisterQuest;
v2RegisterQuest=function(k){v3OldRegisterQuest(k);v3RegisterSubmissions(k);v3BuildSearch();};
const v3OldSaveForm=saveForm;
saveForm=function(f){if(f.dataset.form.startsWith('submit-')){const id=f.dataset.form.slice(7),k=questData.find(k=>k.id===id);if(!v3Teacher()&&k?.course!==U.activeCourse){go('/learning');return;}const values=Object.fromEntries([...new FormData(f)].map(([k,v])=>[k,typeof v==='string'?v.slice(0,700):v.name]));U.submissions[id]={...U.submissions[id],...values,status:'submitted'};v3OldSaveForm(f);return;}if(f.dataset.form.startsWith('v3-project-')){const d=Object.fromEntries(new FormData(f));let p=projects.find(p=>p.id===f.dataset.form.slice(11));if(!p){p={id:'mine-'+Date.now(),owner:'Alex Jensen',ownerId:'me',tag:'Eget projekt'};projects.push(p);}Object.assign(p,{name:String(d.title).slice(0,120),desc:String(d.body).slice(0,700),visibility:d.visibility,cover:d.cover});U.customProjects=projects.filter(p=>p.id.startsWith('mine-')||p.ownerId==='me').map(p=>({...p}));v3RegisterProject(p);v3BuildSearch();state.notice='Projektet er gemt '+(p.visibility==='public'?'og vises i fællesgalleriet.':'som dit private projekt.');go('/projects/'+p.id);return;}v3OldSaveForm(f);};

function v3Medal(b,preview=null){const n=preview??Number(V.ranks[b.id]||0),rank=b.type==='Emne'?Math.max(1,n):3,glyph=b.name.split(/\s+/).slice(0,2).map(w=>w[0]).join(''),label=b.type==='Emne'?(n?rankNames[n-1]:'Mangler'):(n?'Opnået':'Mangler');return `<div class="v3-medal v3-rank-${rank} ${n?'':'locked'}" role="img" aria-label="${E(b.name+' · '+label)}"><div class="v3-badge-shell"></div><div class="v3-medal-center"><span class="badge-glyph">${E(glyph)}</span>${icon(b.icon)}</div><span class="v3-medal-stars" aria-hidden="true">${n?'★'.repeat(b.type==='Emne'?n:1):'○'}</span><span class="v3-medal-ribbon">${label}</span></div>`;}
medal=v3Medal;
function v3BadgeCatalog(wall=false){const owned=badges.filter(b=>V.ranks[b.id]>0),filter=wall?'Mine':V.badgeFilter||'Alle',category=V.badgeCategory||'Alle typer';const visible=badges.filter(b=>(!wall||V.ranks[b.id]>0)&&(category==='Alle typer'||b.type===category)&&(filter==='Alle'||filter==='Mine'&&V.ranks[b.id]>0||filter==='Mangler'&&!V.ranks[b.id]||filter==='I gang'&&state.badges[b.id]==='progress'&&!V.ranks[b.id]));return `${title(wall?'Mine badges':'Små beviser på det, du kan.',wall?'Dine opnåede badges og de niveauer, du har nået.':'Fra at forklare et emne til at undervise andre i det.')}<div class="v3-badge-intro"><div><strong>${owned.length} opnåede · ${badges.length-owned.length} mangler</strong><div class="v3-rank-key">${rankNames.map((name,i)=>`<span class="v3-rank-${i+1}"><i aria-hidden="true"></i>${i+1}. ${name}</span>`).join('')}</div><p>Hvert emne har fem niveauer med hver sin medalje. Særlige badges har ét selvstændigt kriterium.</p></div>${A(wall?'/badges':'/progress/badges',wall?'Se hele badgekataloget':'Se kun mine badges','secondary')}</div>${!wall?`<div class="filters">${['Alle','Mine','Mangler','I gang'].map(t=>`<button class="filter" data-v2="badge-filter" data-value="${t}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div>`:''}<label class="field" style="max-width:240px">Type<select data-v2-change="badge-category">${['Alle typer','Emne','Særlig','Social','Forløb'].map(t=>`<option ${category===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="badge-grid">${visible.map(b=>{const n=V.ranks[b.id]||0;return `<a class="badge-card ${n?'':'not-owned'} v3-rank-${Math.max(n,1)}" href="#/badges/${b.id}"><span class="v3-badge-type">${b.type}</span>${v3Medal(b)}<h2>${E(b.name)}</h2><p>${E(b.desc)}</p><span class="v3-badge-status">${n?'✓ Opnået'+(b.type==='Emne'?' · '+rankNames[n-1]:''):'○ Mangler'}</span>${b.type==='Emne'?`<div class="v3-badge-progress" aria-label="${n} af 5 niveauer opnået">${Array.from({length:5},(_,i)=>`<span class="${i<n?'on':''}"></span>`).join('')}</div><span class="tiny muted">${n}/5 niveauer</span>`:'<span class="tiny muted" style="margin-top:12px">Særligt kriterium</span>'}</a>`;}).join('')||'<div class="empty">Ingen badges i dette udvalg.</div>'}</div>`;}
function v3BadgeDetail(b){const n=Number(V.ranks[b.id]||0),selected=U.previewRank[b.id]||Math.min(5,n+1),m=modules.find(m=>m.id===b.module);return `${title(b.name,b.desc)}${b.type==='Emne'?`<div class="v3-rank-buttons" aria-label="Se badgekrav pr. niveau">${rankNames.map((r,i)=>`<button type="button" class="v3-rank-button" data-v3="preview-rank" data-id="${b.id}" data-rank="${i+1}" aria-pressed="${selected===i+1}">${v3Medal(b,i+1)}<span>${r}</span><small>${i<n?'✓ Opnået':i===n?'Næste niveau':'Ikke opnået'}</small></button>`).join('')}</div><section class="v3-rank-detail" aria-live="polite"><div class="v3-step-strip">${selected<=n?pill('✓ Opnået','green'):pill(selected===n+1?'Dit næste niveau':'Ikke opnået')}</div><h2>${rankNames[selected-1]}</h2><p>${E(ranks[selected-1])}</p>${selected>1?`<p class="tiny">Bygger videre på ${rankNames[selected-2]} i samme emne.</p>`:''}</section>`:`<section class="v3-rank-detail">${v3Medal(b)}<h2>${n?'✓ Opnået':'Mangler'}</h2><p>${E(b.desc)}</p><p>Underviseren bekræfter, at kriteriet er opfyldt. Dette badge bruger ikke de fem emneniveauer.</p></section>`}<div class="actions">${m?A(m.path,'Arbejd med emnet','action'):''}${A('/badges','Tilbage til badgekataloget','secondary')}${v3Teacher()?A('/teacher/badges','Tildel et niveau','secondary'):''}</div>`;}
v2BadgeList=v3BadgeCatalog;v2BadgeDetail=v3BadgeDetail;
for(const b of badges)add('/badges/'+b.id,b.name,'Badges',()=>v3BadgeDetail(b),'badges');

for(const p of projects)Object.assign(p,{owner:'Alex Jensen',ownerId:'me',visibility:p.id==='rune'?'public':'private',cover:p.id==='rune'?'project':'h3'});
for(const p of [{id:'greenhouse',name:'Det lille drivhus',desc:'Temperatur og lys fra et drivhus, samlet i et enkelt dashboard.',tag:'H3 · IoT',owner:'Sofie & Mikkel',ownerId:'other',visibility:'public',cover:'h3'},{id:'maze',name:'Runernes labyrint',desc:'Et spil om at vælge sin vej og bruge information fra tidligere forsøg.',tag:'Game Design',owner:'Noah',ownerId:'other',visibility:'public',cover:'game'}])if(!projects.some(x=>x.id===p.id))projects.push(p);
for(const p of U.customProjects){const existing=projects.find(x=>x.id===p.id);if(existing)Object.assign(existing,p);else projects.push(p);}
projectList=function(own=false){const visible=projects.filter(p=>own?p.ownerId==='me':p.visibility==='public');return `${title(own?'Mine projekter':'Fælles projektgalleri',own?'Dine projekter. Du vælger selv, hvad der deles med andre.':'Projekter, eleverne har valgt at dele. Private afleveringer vises aldrig her.')}<div class="v3-task-tabs">${A('/projects/mine','Mine projekter',own?'v3-current':'')}${A('/explore/projects','Fælles galleri',!own?'v3-current':'')}</div>${own?`<div class="actions" style="margin-bottom:20px">${A('/projects/new','Opret projekt','action')}</div>`:''}<div class="tiles">${visible.map(p=>`<a class="tile" href="#/projects/${p.id}">${v2Cover(p.cover,'v2-card-image')}${pill(p.tag)}<h2>${E(p.name)}</h2><p>${E(p.desc)}</p><div class="v3-visibility">${E(p.owner)} · ${p.visibility==='public'?'Delt i fællesgalleriet':'Kun mig'}</div></a>`).join('')}</div>`;};
function v3RegisterProject(p){add('/projects/'+p.id,p.name,'Projekter',()=>`${title(p.name,p.desc)}${v2Cover(p.cover,'v2-project-image')}<div class="cols" style="margin-top:22px"><article class="article"><h2>Om projektet</h2><p>${E(p.desc)}</p><p class="tiny">Genereret cover · Fiktivt eksempelprojekt</p>${p.ownerId==='me'?`<div class="actions">${A('/projects/'+p.id+'/edit','Redigér mit projekt','action')}</div>`:''}<h3>Projekt og aflevering</h3><p>Dette er en præsentation af projektet. En privat aflevering til en quest indsendes separat under “Quests og afleveringer”.</p><div class="actions">${A(p.ownerId==='me'?'/projects/mine':'/explore/projects',p.ownerId==='me'?'Tilbage til mine projekter':'Tilbage til fællesgalleriet','secondary')}</div></article><aside class="panel"><h2>${E(p.owner)}</h2><p>${p.visibility==='public'?'Delt i fællesgalleriet':'Privat projekt · Kun mig'}</p><p>${p.tag}</p></aside></div>`,'projects');if(p.ownerId==='me')add('/projects/'+p.id+'/edit','Redigér · '+p.name,'Projektredigering',()=>v3ProjectEditor(p),'projects');}
function v3ProjectEditor(p=null){return `${title(p?'Redigér mit projekt':'Opret et projekt','En showcase er adskilt fra dine private quest-afleveringer.')}<section class="panel"><form data-form="v3-project-${p?.id||'new'}"><label class="field">Projektnavn<input name="title" required value="${E(p?.name||'')}"></label><label class="field">Hvad har du bygget?<textarea name="body" required>${E(p?.desc||'')}</textarea></label><label class="field">Synlighed<select name="visibility"><option value="private" ${p?.visibility!=='public'?'selected':''}>Kun mig</option><option value="public" ${p?.visibility==='public'?'selected':''}>Del i fællesgalleriet</option></select></label><label class="field">Cover<select name="cover">${[['project','2D-spil'],['h3','IoT og dashboard'],['game','Game Design']].map(([v,t])=>`<option value="${v}" ${p?.cover===v?'selected':''}>${t}</option>`).join('')}</select></label><button type="button" class="action" data-action="save-form">Gem projekt</button></form></section>`;}
projects.forEach(v3RegisterProject);add('/projects/new','Opret mit projekt','Projekter',()=>v3ProjectEditor(),'projects');

const v3Shop=[{id:'lamp',cost:80},{id:'trophy',cost:140}];
function v3ShopPage(){return `${title('Små ting til dit eget sted.','Brug guld fra godkendte quests på møbler til din 2D-lejlighed.')}<div class="v3-wallet-panel"><div class="v3-gold"><strong><i class="v3-gold-dot" aria-hidden="true"></i>${v3Num(U.gold)}</strong><span>Guld til rådighed</span></div><div><strong>${v3Level()}</strong><span>Dit level</span></div></div><div class="tiles">${v3Shop.map(item=>{const f=v2Furniture.find(f=>f.id===item.id),owned=U.owned.includes(f.id),unlocked=v3Level()>=f.level;return `<section class="panel"><div class="v3-shop-preview">${v2Furn(f.id)}</div><h2>${f.name}</h2><p>Åbner ved level ${f.level} · ${item.cost} guld</p><button type="button" class="${owned?'secondary':'action'}" data-v3="buy" data-id="furniture-${f.id}" ${owned||!unlocked||U.gold<item.cost?'disabled':''}>${owned?'✓ Ejet':!unlocked?'Kræver level '+f.level:U.gold<item.cost?'Du mangler guld':'Køb for '+item.cost+' guld'}</button></section>`;}).join('')}</div><div class="actions">${A('/apartment','Indret min lejlighed','secondary')}${A('/progress','Se hvordan du får guld','secondary')}</div>`;}
v2Apartment=function(){const selected=V.selectedCell!==null?V.room[V.selectedCell]:null;return `${title('Min lejlighed','Vælg et møbel, og placér det på et frit felt. Klik på et møbel for at flytte det.')}<div class="cols"><section class="v2-room-wrap"><div class="v2-room" aria-label="Dit rum, 8 gange 6 felter">${Array.from({length:48},(_,i)=>{const f=v2Furniture.find(f=>f.id===V.room[i]);return `<button type="button" class="v2-room-cell" data-v2="room-cell" data-cell="${i}" aria-label="Række ${Math.floor(i/8)+1}, felt ${i%8+1}${f?', '+f.name:', tomt'}" aria-pressed="${V.selectedCell===i}">${f?v2Furn(f.id):''}</button>`;}).join('')}</div><p class="v2-status" aria-live="polite">${E(V.roomNotice||(V.moving!==null?'Vælg et frit felt at flytte til.':V.selectedItem?'Valgt: '+(v2Furniture.find(f=>f.id===V.selectedItem)?.name||'møbel'):'Vælg et møbel fra inventaret.'))}</p>${selected?`<div class="actions"><button class="secondary" data-v2="move-furniture">Flyt møbel</button><button class="secondary" data-v2="remove-furniture">Tilbage til inventar</button></div>`:''}</section><aside class="aside"><section class="panel"><h2>Mit inventar</h2><div class="v2-inventory">${v2Furniture.filter(f=>U.owned.includes(f.id)).map(f=>{const placed=Object.values(V.room).includes(f.id);return `<button class="v2-item" data-v2="choose-furniture" data-id="${f.id}" aria-pressed="${V.selectedItem===f.id}" ${placed?'disabled':''}>${v2Furn(f.id)}<span>${f.name}<br><span class="muted">${placed?'I rummet':'Klar til brug'}</span></span></button>`;}).join('')}</div><div class="actions">${A('/universe/shop','Køb møbler · '+U.gold+' guld','secondary')}</div></section><section class="panel"><div class="person">${v2Sprite()}<div><h2>Min avatar</h2>${A('/profile/character','Tilpas din figur')}</div></div></section></aside></div>`;};
function v3Progress(){return `${title('Din udvikling','XP viser din progression. Guld kan bruges på ting til dit univers.')}<div class="v3-wallet-panel"><div><strong>Level ${v3Level()}</strong><span>${200-U.xp%200} XP til næste level</span></div><div><strong>${v3Num(U.xp)}</strong><span>Samlet karriere-XP</span></div><div class="v3-gold"><strong><i class="v3-gold-dot" aria-hidden="true"></i>${v3Num(U.gold)}</strong><span>Guld</span></div></div><div class="cols"><section class="panel"><h2>På vej mod level ${v3Level()+1}</h2><div class="v3-level-track" role="progressbar" aria-label="XP mod næste level" aria-valuenow="${U.xp%200}" aria-valuemin="0" aria-valuemax="200"><span style="width:${U.xp%200/2}%"></span></div><p>${U.xp%200}/200 XP på dette level</p><h3 style="margin-top:24px">Forløbs-XP</h3>${courseData.map(c=>row(c.name,v3Num(U.courseXP[c.id]||0)+' forløbs-XP',cp(c),'','book-open')).join('')}<h3 style="margin-top:24px">Sådan får du belønninger</h3><p>En quest giver XP og guld, når underviseren godkender din aflevering. Du får belønningen én gang pr. quest. At åbne en side eller aflevere igen giver ikke ekstra XP.</p><p class="tiny">Demoregel: 200 XP pr. level og 1 guld pr. 5 XP. Beløbene er forslag.</p></section><aside class="aside"><section class="panel"><h2>Brug dit guld</h2><p>Gør dit rum til dit eget.</p>${A('/universe/shop','Åbn møbelbutikken','action')}</section><section class="panel"><h2>Dine badges</h2><p>Badgeniveauer viser, hvad du kan demonstrere. De er adskilt fra dit samlede level.</p>${A('/progress/badges','Se mine badges','secondary')}</section></aside></div><div class="headrow"><h2>Seneste belønninger og køb</h2></div>${U.ledger.slice().reverse().map(x=>`<div class="v3-task"><div><h3>${E(x.name)}</h3><p>${x.xp?'+'+x.xp+' XP · ':''}${x.gold>0?'+':''}${x.gold} guld</p></div></div>`).join('')||'<p class="small muted">Din saldo er et eksempel. Nye godkendelser og køb vises her.</p>'}`;}

function v3BuildSearch(){v3SearchIndex=[...courseData.map(c=>({title:c.name,text:c.desc,path:cp(c),type:'Forløb',context:c.duration})),...courseData.flatMap(c=>c.subjects.map(s=>({title:s.name,text:s.desc||c.desc,path:sp(c,s),type:'Fag',context:c.name}))),...modules.map(m=>({title:m.name,text:(m.desc||'')+' '+(m.lesson||''),path:m.path,type:'Emner',context:m.c.name+' / '+m.s.name})),...questData.map(k=>({title:k.name,text:k.desc,path:'/quests/'+k.id,type:'Quests',context:k.course==='h3'?'H3':'Game Design'})),...badges.map(b=>({title:b.name,text:b.desc,path:'/badges/'+b.id,type:'Badges',context:'Badge · '+b.topic})),...projects.filter(p=>p.visibility==='public'||p.ownerId==='me').map(p=>({title:p.name,text:p.desc,path:'/projects/'+p.id,type:'Projekter',context:p.owner+' · '+(p.visibility==='public'?'Fælles galleri':'Mit private projekt')})),...[['Min læring','/learning'],['Ugekalender','/calendar'],['Mine afleveringer','/submissions'],['Min logbog','/journal'],['Min avatar','/profile/character'],['Min lejlighed','/apartment'],['Møbelbutik','/universe/shop'],['XP, level og guld','/progress'],['Stemningstjek','/checkin']].filter(([n,p])=>U.activeCourse||!['/calendar','/submissions','/journal','/checkin'].includes(p)).map(([title,path])=>({title,path,text:'',type:'Sider',context:'Navigation'}))];}
function v3Results(){v3BuildSearch();const term=U.query.trim().toLocaleLowerCase('da-DK'),words=term.split(/\s+/).filter(Boolean);if(!words.length)return '<p class="muted small">Søg efter et emne, en quest, et badge eller et projekt.</p>';const results=v3SearchIndex.filter(r=>(U.searchType==='Alle'||r.type===U.searchType)&&words.every(w=>(r.title+' '+r.text+' '+r.context).toLocaleLowerCase('da-DK').includes(w))).sort((a,b)=>Number(b.title.toLowerCase().includes(term))-Number(a.title.toLowerCase().includes(term)));return `<p class="small muted" aria-live="polite">${results.length} resultater for “${E(U.query)}”</p>${results.slice(0,40).map(r=>`<a class="v3-result" href="#${r.path}"><small>${E(r.type+' · '+r.context)}</small><h2>${E(r.title)}</h2><p>${E(r.text)}</p></a>`).join('')||'<div class="v3-empty"><h2>Ingen resultater</h2><p>Prøv et kortere søgeord eller en anden kategori.</p></div>'}`;}
function v3SearchPage(){return `${title('Find det, du leder efter.','Søg på tværs af forløb, fag, emner, quests, projekter og badges.')}<div class="v3-search-controls"><label class="field">Søg<input id="v3-query" type="search" value="${E(U.query)}" placeholder="F.eks. MQTT, GDD eller badge …"></label><label class="field">Kategori<select data-v3-change="search-type">${['Alle','Forløb','Fag','Emner','Quests','Projekter','Badges','Sider'].map(t=>`<option ${U.searchType===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="v3-search-results" class="v3-search-results">${v3Results()}</div>`;}

