function v3Gated(path){return path==='/calendar'||path==='/quests'||path==='/submissions'||path==='/checkin'||path==='/attention'||path.startsWith('/journal')||/^\/quests\/[^/]+\/submit$/.test(path)||/^\/courses\/[^/]+\/(calendar|quests|submissions|journal|days)(\/|$)/.test(path);}
const v3PrevRender=render;
function v3RunSearch(formElement){U.query=String(new FormData(formElement).get('query')||'').slice(0,120);go('/search');}
render=function(){if(route.startsWith('/teacher'))state.role='teacher';else if(route==='/student')state.role='student';if(!v3Teacher()&&!U.activeCourse&&v3Gated(route))route='/learning';if(!v3Teacher()&&/^\/quests\/[^/]+\/submit$/.test(route)){const k=questData.find(k=>route==='/quests/'+k.id+'/submit');if(k&&k.course!==U.activeCourse)route='/quests/'+k.id;}if(!v3Teacher()){const c=courseData.find(c=>route.startsWith(cp(c)+'/'));if(c&&c.id!==U.activeCourse&&/^\/courses\/[^/]+\/(calendar|quests|submissions|journal|days)(\/|$)/.test(route))route=cp(c);}if(route==='/checkin')V.mood.selection=U.checkins[U.activeCourse]??null;root.dataset.theme=U.theme;v3PrevRender();q('.app>header').innerHTML=v3Header();q('.proto-bar').innerHTML=`<span>Campus · Designskabelon</span><div class="proto-actions"><label class="v3-demo-select">Forløbstilstand<select data-v3-change="active-course" aria-label="Afprøv tilmelding til et forløb"><option value="h3" ${U.activeCourse==='h3'?'selected':''}>H3 aktivt</option><option value="game" ${U.activeCourse==='game'?'selected':''}>Game Design aktivt</option><option value="" ${!U.activeCourse?'selected':''}>Intet aktivt forløb</option></select></label><button type="button" data-role="student" aria-pressed="${!v3Teacher()}">Elev</button><button type="button" data-role="teacher" aria-pressed="${v3Teacher()}">Underviser</button><a href="#/sitemap">Alle sider</a></div>`;q('.app>header').insertAdjacentHTML('afterend',`<div id="v3-course-context">${v3Breadcrumb()}${v3Reminder()}</div>`);qa('#v3-course-context').slice(1).forEach(e=>e.remove());if(q('.v3-context'))qa('#campus-content>.breadcrumbs').forEach(e=>e.remove());qa('.v3-task-tabs .v3-current').forEach(a=>a.setAttribute('aria-current','page'));const toc=q('.v2-toc');if(toc){toc.remove();q('.v2-notion')?.classList.add('v3-notion');}v3InactivePreview();if(globalThis.lucide){lucide.createIcons({attrs:{width:18,height:18}});q('.app').classList.add('icons-ready');}};
const v3PrevGo=go;
go=function(path,save=true){qa('.v3-navgroup[open],.v3-context details[open]').forEach(d=>d.open=false);v3PrevGo(path,save);};
remember=function(){stateRevision++;v3AppliedRevision=stateRevision;if(!window.lupState?.setWidgetState)return;const vs=JSON.parse(JSON.stringify(V)),us=JSON.parse(JSON.stringify(U));vs.questDraft=null;us.ledger=us.ledger.slice(-12);Object.values(us.submissions).forEach(s=>{if(s.comment)s.comment=String(s.comment).slice(0,500);if(s.feedback)s.feedback=String(s.feedback).slice(0,500);});const demoState={role:state.role,badges:state.badges,completed:state.completed,notes:state.notes.slice(-2).map(n=>({...n,title:String(n.title||'').slice(0,100),body:String(n.body||'').slice(0,250)})),submission:state.submission,approved:state.approved,v2:vs,v3:us};const payload={modelContent:{page:route,role:state.role,concept:'Campus v3',theme:U.theme,activeCourse:U.activeCourse,xp:U.xp,level:v3Level(),gold:U.gold,revision:stateRevision},privateContent:{demoState}};let n=0;while(new TextEncoder().encode(JSON.stringify(payload)).length>15000&&n++<100){if(vs.slots.length>11)vs.slots.shift();else if(vs.customQuests.length>1)vs.customQuests.shift();else if(us.ledger.length)us.ledger.shift();else if(demoState.notes.length)demoState.notes.pop();else if(us.customProjects.length>2)us.customProjects.shift();else if(Object.keys(vs.specs).length>2)delete vs.specs[Object.keys(vs.specs)[0]];else break;}if(new TextEncoder().encode(JSON.stringify(payload)).length<=16000)window.lupState.setWidgetState(payload).catch(()=>{});};
root.addEventListener('click',event=>{const searchButton=event.target.closest('.v3-search button');if(searchButton){event.preventDefault();event.stopImmediatePropagation();v3RunSearch(searchButton.closest('form'));return;}const b=event.target.closest('[data-v3]');if(b){event.preventDefault();event.stopImmediatePropagation();if(b.dataset.v3==='preview-rank'){U.previewRank[b.dataset.id]=Number(b.dataset.rank);render();remember();return;}if(b.dataset.v3==='approve'){const k=questData.find(k=>k.id===b.dataset.id),s=U.submissions[k?.id];if(!v3Teacher()||!s)return;s.feedback=q('#v3-feedback')?.value.slice(0,700)||s.feedback||'Dit arbejde er godkendt.';s.status='approved';if(!U.rewarded.includes(k.id)){const xp=Math.max(0,Number(V.specs[k.id]?.xp||100)),gold=Math.round(xp/5);U.xp+=xp;U.gold+=gold;U.courseXP[k.course]=(U.courseXP[k.course]||0)+xp;U.rewarded.push(k.id);U.ledger.push({name:k.name,xp,gold});state.notice=`Godkendt. Alex har fået ${xp} XP og ${gold} guld.`;}else state.notice='Godkendt igen. Belønningen er allerede tildelt.';state.approved=true;render();remember();return;}if(b.dataset.v3==='buy'){const id=b.dataset.id.replace('furniture-',''),item=v3Shop.find(i=>i.id===id),f=v2Furniture.find(f=>f.id===id);if(!item||U.owned.includes(id)||U.gold<item.cost||v3Level()<f.level)return;U.gold-=item.cost;U.owned.push(id);U.ledger.push({name:'Købt '+f.name.toLowerCase(),xp:0,gold:-item.cost});state.notice=f.name+' er nu i dit inventar.';render();remember();return;}}
 const mood=event.target.closest('[data-v2="mood-vote"]');if(mood){event.preventDefault();event.stopImmediatePropagation();if(!U.activeCourse||!V.mood.open)return;U.checkins[U.activeCourse]=Number(mood.dataset.index);V.mood.selection=Number(mood.dataset.index);render();remember();return;}
 const newMood=event.target.closest('[data-v2="mood-new"]');if(newMood){event.preventDefault();event.stopImmediatePropagation();delete U.checkins[U.activeCourse||V.mood.course];V.mood={...V.mood,course:U.activeCourse||V.mood.course,open:true,selection:null,counts:[0,0,0,0,0]};render();remember();}
},true);
root.addEventListener('change',event=>{const kind=event.target.dataset.v3Change;if(kind==='theme'){U.theme=event.target.value;root.dataset.theme=U.theme;remember();return;}if(kind==='active-course'){U.activeCourse=event.target.value||null;V.calendarCourse=U.activeCourse||'all';V.mood.course=U.activeCourse||'h3';V.mood.selection=U.checkins[U.activeCourse]??null;state.notice='';go(state.role==='teacher'?'/teacher':'/student');return;}if(kind==='search-type'){U.searchType=event.target.value;q('#v3-search-results').innerHTML=v3Results();remember();}});
root.addEventListener('submit',event=>{if(event.target.dataset.v3Form==='search'){event.preventDefault();U.query=String(new FormData(event.target).get('query')||'').slice(0,120);go('/search');}});
root.addEventListener('input',event=>{if(event.target.id==='v3-query'){U.query=event.target.value.slice(0,120);q('#v3-search-results').innerHTML=v3Results();remember();}});
root.addEventListener('toggle',event=>{const d=event.target;if(d.matches?.('.v3-navgroup,.v3-context details')&&d.open)qa('.v3-navgroup[open],.v3-context details[open]').filter(x=>x!==d).forEach(x=>x.open=false);},true);
root.addEventListener('click',event=>{qa('.v3-navgroup[open],.v3-context details[open]').forEach(d=>{if(!d.contains(event.target))d.open=false;});});
root.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.closest('.v3-search')){event.preventDefault();v3RunSearch(event.target.closest('form'));return;}if(event.key==='Escape'){const d=event.target.closest('details[open]');if(d){d.open=false;d.querySelector('summary')?.focus();}}});
window.addEventListener('lup:state',event=>{const saved=event.detail?.globals?.widgetState,demo=saved?.privateContent?.demoState,r=Number(saved?.modelContent?.revision||0);if(!demo?.v3||r<=v3AppliedRevision)return;v3AppliedRevision=r;stateRevision=Math.max(stateRevision,r);Object.assign(U,demo.v3);if(demo.v2)Object.assign(V,demo.v2);if(demo.role)state.role=demo.role;if(demo.badges)state.badges=demo.badges;for(const k of V.customQuests||[]){const old=questData.find(x=>x.id===k.id);if(old)Object.assign(old,k);else questData.push(k);v2RegisterQuest(k);}for(const p of U.customProjects||[]){const old=projects.find(x=>x.id===p.id);if(old)Object.assign(old,p);else projects.push(p);v3RegisterProject(p);}v3BuildSearch();if(saved.modelContent?.page&&routes.has(saved.modelContent.page))route=saved.modelContent.page;render();});

