function v4Item(id){return v4Items.find(i=>i.id===id);}
function v4Owned(i){return i.kind==='Tøj'?W.ownedWear.includes(i.id):U.owned.includes(i.id);}
function v4Requirements(i){return {level:v3Level()>=i.level,badge:!i.badge||Number(V.ranks[i.badge]||0)>=(i.rank||1)};}
function v4Unlocked(i){const r=v4Requirements(i);return r.level&&r.badge;}
function v4BadgeName(i){const b=badges.find(b=>b.id===i.badge);return b?b.name+(b.type==='Emne'?' · '+rankNames[(i.rank||1)-1]:''):'';}
function v4LockText(i){const r=v4Requirements(i),parts=[];if(!r.level)parts.push('Level '+i.level);if(!r.badge)parts.push(v4BadgeName(i));return parts.length?'Kræver '+parts.join(' og '):i.badge?'Åben via '+v4BadgeName(i):'Åben fra level '+i.level;}
function v4Shirt(i){return `<span class="v4-shirt ${i.style}" style="--cloth:${i.color||V.avatar.outfit};--cloth-light:#ffffff60" aria-hidden="true"></span>`;}
function v4Art(i){return `<div class="v4-product-art">${i.kind==='Tøj'?v4Shirt(i):v2Furn(i.id)}</div>`;}
function v4ItemAction(i){const owned=v4Owned(i),unlocked=v4Unlocked(i),enough=U.gold>=i.cost;if(owned)return i.kind==='Tøj'?`<button type="button" class="secondary" data-v4="equip" data-id="${i.id}" ${W.equipped===i.id?'disabled':''}>${W.equipped===i.id?'✓ På din avatar':'Tag på'}</button>`:A('/apartment','Indret med møblet','secondary');return `<button type="button" class="${unlocked&&enough?'action':'secondary'}" data-v4="buy" data-id="${i.id}" ${!unlocked||!enough?'disabled':''}>${!unlocked?'Låst':!enough?'Mangler '+(i.cost-U.gold)+' guld':i.kind==='Tøj'?'Køb og tag på · '+i.cost+' guld':'Køb · '+i.cost+' guld'}</button>`;}
function v4Product(i){return `<section class="v4-product ${v4Unlocked(i)?'':'is-locked'}">${v4Art(i)}<h2>${A('/universe/shop/items/'+i.id,i.name)}</h2><p>${E(i.desc)}</p><div class="v4-product-lock ${v4Unlocked(i)?'is-ready':''}"><span aria-hidden="true">${v4Owned(i)?'✓':v4Unlocked(i)?'○':'◇'}</span><span>${v4Owned(i)?'Ejet':E(v4LockText(i))}</span></div><div class="v4-product-price">${i.cost?'<i class="v3-gold-dot" aria-hidden="true"></i>'+i.cost+' guld':'Startinventar'}</div><div class="actions">${v4ItemAction(i)}</div></section>`;}
function v4Shop(){const next=Math.min(...v4Items.filter(i=>i.level>v3Level()).map(i=>i.level));return `${title('Butik til dit univers','Møbler til dit rum og tøj til din fælles spilavatar.')}<div class="v4-shop-summary"><div><strong><i class="v3-gold-dot" aria-hidden="true"></i>${v3Num(U.gold)} guld</strong><p>Level ${v3Level()}${Number.isFinite(next)?' · Nye ting ved level '+next:''}</p></div>${A('/universe/unlocks','Se alle level- og badge-oplåsninger','secondary')}</div><div class="v4-shop-tabs" aria-label="Butikskategorier">${['Tøj','Møbler','Alle'].map(c=>`<button type="button" class="filter" data-v4="shop-category" data-value="${c}" aria-pressed="${W.shopCategory===c}">${c==='Tøj'?'Avatartøj':c}</button>`).join('')}${A('/profile/character','Min garderobe','secondary')}</div><div class="v4-shop-grid">${v4Items.filter(i=>W.shopCategory==='Alle'||i.kind===W.shopCategory).map(v4Product).join('')}</div><p class="tiny muted" style="margin-top:18px">Et level eller badge åbner købet. Du ejer først varen, når du har købt den med guld.</p>`;}
function v4ItemPage(i){const r=v4Requirements(i);return `${title(i.name,i.kind,[['Butik','/universe/shop'],[i.name]])}<div class="v4-item-hero">${v4Art(i)}<section><h2 style="font-size:26px">${i.cost?i.cost+' guld':'Dit startsæt'}</h2><p class="small muted" style="margin-top:10px">${E(i.desc)}</p><ul class="v4-requirements"><li class="${r.level?'passed':''}">${r.level?'✓':'○'} Level ${i.level} · Du er level ${v3Level()}</li>${i.badge?`<li class="${r.badge?'passed':''}">${r.badge?'✓':'○'} ${A('/badges/'+i.badge,v4BadgeName(i))}</li>`:''}<li class="${v4Owned(i)?'passed':''}">${v4Owned(i)?'✓ Du ejer varen':'○ Køb varen for at føje den til '+(i.kind==='Tøj'?'din garderobe':'dit inventar')}</li></ul><div class="actions">${v4ItemAction(i)}${A(i.kind==='Tøj'?'/profile/character':'/apartment',i.kind==='Tøj'?'Se min avatar':'Se min lejlighed','secondary')}</div><p class="tiny muted" style="margin-top:15px">Din saldo: ${U.gold} guld.</p></section></div>`;}
function v4UnlockRow(i){return `<div class="v4-unlock-row">${v4Art(i)}<div><strong>${E(i.name)}</strong><small>${i.kind} · ${i.cost?i.cost+' guld':'Startinventar'}${i.badge?' · Også '+E(v4BadgeName(i)):''}</small></div>${A('/universe/shop/items/'+i.id,v4Owned(i)?'Ejet':v4Unlocked(i)?'Se varen':'Se krav')}</div>`;}
function v4LevelSection(l,next){return `<section class="v4-level-node ${l<=v3Level()?'reached':l===next?'next':''}"><h2>Level ${l} ${pill(l<=v3Level()?'✓ Level nået':l===next?'Næste oplåsning':'Låst',l<=v3Level()?'green':'')}</h2>${v4Items.filter(i=>i.level===l).map(v4UnlockRow).join('')}</section>`;}
function v4Unlocks(){const levels=[...new Set(v4Items.map(i=>i.level))].sort((a,b)=>a-b),next=levels.find(l=>l>v3Level()),past=levels.filter(l=>l<=v3Level());return `${title('Det næste, du kan låse op','Se både levelkrav og badges. En oplåsning åbner for køb med guld.')}<div class="v4-shop-summary"><div><strong>Level ${v3Level()}</strong><p>${200-U.xp%200} XP til næste level · ${U.gold} guld</p></div>${A('/universe/shop','Til butikken','secondary')}</div><div class="v4-roadmap">${levels.filter(l=>l>v3Level()).map(l=>v4LevelSection(l,next)).join('')||'<p class="small muted">Du har nået alle butikkens levelkrav.</p>'}</div><details class="v4-past-levels"><summary>Se allerede nåede levels</summary><div class="v4-roadmap">${past.map(l=>v4LevelSection(l,next)).join('')}</div></details><div class="v4-section"><h2>Badges åbner særlige ting</h2><p>Level og badge skal begge være på plads, hvis varen har begge krav.</p></div><section class="panel">${v4Items.filter(i=>i.badge).map(v4UnlockRow).join('')}</section>`;}
const v4BaseSprite=v2Sprite;
v2Sprite=function(mini=false){const i=v4Item(W.equipped)||v4Item('basic');let html=v4BaseSprite(mini);html=html.replace('class="v2-sprite ','class="v2-sprite wear-'+i.style+' ');if(i.color)html=html.replace(/--outfit:#[0-9a-f]{6}/i,'--outfit:'+i.color);return html;};
v2AvatarPage=function(){const swatches={skin:[['#edc5a2','Lys'],['#c98d69','Mellem'],['#8d5e44','Brun'],['#553b33','Mørk']],hair:[['#42302a','Mørk'],['#a76636','Brun'],['#d5ac62','Lys'],['#545ca0','Lilla']]};return `${title('Min avatar og garderobe','Dit købte tøj følger figuren ind i dit univers og prøvespillet.')}<div class="cols"><section class="panel"><div class="v2-avatar-stage" role="img" aria-label="Din avatar med ${E(v4Item(W.equipped)?.name||'basis-T-shirt')}">${v2Sprite()}</div><h2>${E(v4Item(W.equipped)?.name||'Basis-T-shirt')}</h2><div class="actions">${A('/games/avatar-demo','Prøv avataren i et spil','action')}${A('/universe/shop','Køb tøj i butikken','secondary')}</div><div class="headrow"><h2>Min garderobe</h2><span>${W.ownedWear.length} sæt</span></div><div class="v4-wardrobe">${v4Items.filter(i=>i.kind==='Tøj'&&v4Owned(i)).map(i=>`<button type="button" data-v4="equip" data-id="${i.id}" aria-pressed="${W.equipped===i.id}">${v4Shirt(i)}<span>${i.name}</span>${W.equipped===i.id?'<span>✓ På</span>':''}</button>`).join('')}</div>${A('/universe/unlocks','Se kommende tøj og oplåsninger')}</section><aside class="aside"><section class="panel"><h2>Dit udtryk</h2>${Object.entries(swatches).map(([key,values])=>`<strong class="small">${key==='skin'?'Hudtone':'Hårfarve'}</strong><div class="v2-options">${values.map(([color,name])=>`<button type="button" class="v2-swatch" style="--swatch:${color}" data-v2="avatar-color" data-key="${key}" data-value="${color}" aria-label="${name}" aria-pressed="${V.avatar[key]===color}"></button>`).join('')}</div>`).join('')}<strong class="small">Hår og tilbehør</strong><div class="v2-options">${[['short','Kort hår'],['long','Langt hår'],['cap','Kasket']].map(([v,t])=>`<button class="filter" data-v2="avatar-style" data-value="${v}" aria-pressed="${V.avatar.style===v}">${t}</button>`).join('')}</div>${W.equipped==='basic'?`<strong class="small">Basis-T-shirtens farve</strong><div class="v2-options">${[['#2452e8','Blå'],['#30826a','Grøn'],['#b66291','Rosa'],['#d47837','Orange']].map(([v,t])=>`<button class="v2-swatch" style="--swatch:${v}" data-v2="avatar-color" data-key="outfit" data-value="${v}" aria-label="${t}" aria-pressed="${V.avatar.outfit===v}"></button>`).join('')}</div>`:''}</section><section class="panel"><h2>Badges giver adgang</h2><p>Hawaii-skjorten kræver Hawaii-badget. Fancy Friday åbner et særligt sæt.</p>${A('/universe/unlocks','Se alle krav')}</section></aside></div>`;};
const v4OldBadgeDetail=v3BadgeDetail;
v3BadgeDetail=function(b){const items=v4Items.filter(i=>i.badge===b.id);return v4OldBadgeDetail(b)+(items.length?`<section class="panel" style="margin-top:24px"><h2>Dette badge åbner i butikken</h2><p>Badget åbner købet. Varen købes stadig for guld.</p>${items.map(v4UnlockRow).join('')}</section>`:'');};

function v4CoursePolls(course=U.activeCourse){return W.polls.filter(p=>p.course===course);}
function v4PollVote(p){return W.votes[p.id];}
function v4OpenPolls(){return v4CoursePolls().filter(p=>p.status==='open');}
function v4QuestKey(k){return k.type==='Daily'?k.id+'@'+W.day:k.id;}
function v4Submission(k){const s=U.submissions[k.id];return k.type==='Daily'&&s?.day!==W.day?null:s;}
function v4QuestDone(k){return !!W.done[v4QuestKey(k)]||v4Submission(k)?.status==='approved';}
function v4QuestRow(k){const done=v4QuestDone(k),s=v4Submission(k);return `<article class="v4-activity"><div class="v4-activity-main"><div class="v4-type"><strong>${k.type}</strong><span>${k.type==='Main'?'Obligatorisk':k.type==='Side'?'Valgfri':'Dagens rutine'}</span></div><h3>${A('/quests/'+k.id,k.name)}</h3><p>${E(k.desc)}</p><span class="v4-status ${s?.status==='approved'?'done':s?.status==='submitted'?'waiting':done&&k.type==='Main'?'waiting':done?'done':''}">${s?.status==='approved'?'✓ Godkendt af underviseren':s?.status==='submitted'?'Afleveret · Afventer vurdering':done?(k.type==='Main'?'Arbejde markeret udført · Aflevering mangler':'✓ Markeret udført'+(k.type==='Daily'?' i dag':'')):'Ikke markeret udført'}</span></div><div class="v4-activity-actions"><button type="button" class="secondary v4-done-button" data-v4="quest-done" data-id="${k.id}" aria-pressed="${done}" ${s?.status==='approved'?'disabled':''}>${done?(k.type==='Daily'?'✓ Udført i dag':'✓ Udført'):'Markér udført'}</button>${A(done&&k.type!=='Daily'&&!s?'/quests/'+k.id+'/submit':'/quests/'+k.id,done&&k.type!=='Daily'&&!s?'Lav aflevering':'Åbn quest','secondary')}</div></article>`;}
function v4PollRow(p,teacher=false){const voted=v4PollVote(p)!==undefined,path=teacher?'/teacher/polls/'+p.id:'/polls/'+p.id;return `<article class="v4-activity"><div class="v4-activity-main"><div class="v4-type">${p.status==='open'?'<span class="v4-live-dot" aria-hidden="true"></span>':''}<strong>${v4PollNames[p.type]}</strong><span>${teacher?courseData.find(c=>c.id===p.course).name:p.status==='open'?'Åben nu':'Lukket'}</span></div><h3>${A(path,p.question)}</h3><p>${teacher?({open:'Eleverne kan svare fra deres aktivitetsside.',draft:'Klar til at starte, når du er klar.',closed:'Svarrunden er afsluttet.'})[p.status]:voted?'Dit svar er registreret. Du kan ændre det, mens runden er åben.':'Giv dit svar til klassen.'}</p></div><div class="v4-activity-actions">${A(path,teacher?'Åbn og styr':voted?'✓ Se dit svar':'Svar nu',voted||teacher?'secondary':'action')}${teacher&&p.status==='open'?A('/teacher/polls/'+p.id+'/present','Vis på tavlen','secondary'):''}</div></article>`;}
function v4Activities(){const c=v3Course();if(!c)return `${title('Aktiviteter')}${v3EmptyLearning()}`;const polls=v4OpenPolls(),quests=questData.filter(k=>k.course===c.id),f=W.activityFilter;return `${title('Aktiviteter i '+c.name,'Svar på klassens afstemninger, og hold styr på Main-, Side- og Daily-quests.')}<div class="v4-toolbar"><div class="filters" aria-label="Aktivitetstype">${['Alle','Afstemninger','Main','Side','Daily'].map(t=>{const count=t==='Alle'?polls.length+quests.length:t==='Afstemninger'?polls.length:quests.filter(k=>k.type===t).length;return `<button type="button" class="filter" data-v4="activity-filter" data-value="${t}" aria-pressed="${f===t}">${t} ${count}</button>`;}).join('')}</div><label><input type="checkbox" data-v4-change="only-pending" ${W.onlyPending?'checked':''}>Kun det, jeg mangler</label></div>${f==='Alle'||f==='Afstemninger'?`<section><div class="v4-section"><h2>Afstemninger lige nu</h2><p>${polls.filter(p=>v4PollVote(p)===undefined).length} afventer dit svar</p></div><div class="v4-activity-list">${polls.filter(p=>!W.onlyPending||v4PollVote(p)===undefined).map(p=>v4PollRow(p)).join('')||'<p class="small muted" style="padding:18px 0">Ingen åbne afstemninger mangler dit svar.</p>'}</div></section>`:''}${['Main','Side','Daily'].filter(t=>f==='Alle'||f===t).map(t=>{const list=quests.filter(k=>k.type===t&&(!W.onlyPending||!v4QuestDone(k)));return `<section><div class="v4-section"><h2>${t} quests</h2><p>${({Main:'De fælles opgaver i forløbet. Aflevering og godkendelse vises særskilt.',Side:'Frivillige udfordringer, når du vil gå videre.',Daily:'Små rutiner. Din markering gælder for i dag.'})[t]}</p></div><div class="v4-activity-list">${list.map(v4QuestRow).join('')||'<p class="small muted" style="padding:18px 0">Du er ajour i dette udvalg.</p>'}</div></section>`;}).join('')}<p class="tiny muted" style="margin-top:20px">“Udført” er din egen markering. XP og guld gives, når underviseren godkender questens aflevering eller registrering.</p>`;}
function v4Counts(p){const counts=[...(p.counts||p.options.map(()=>0))],v=v4PollVote(p);if(typeof v==='number'&&counts[v]!==undefined)counts[v]++;return counts;}
function v4Results(p,force=false){const counts=v4Counts(p),total=p.type==='word'?(p.words||[]).length+(typeof v4PollVote(p)==='string'?1:0):counts.reduce((a,b)=>a+b,0);if(!p.showResults&&!force)return `<div class="callout">Resultaterne vises, når underviseren åbner dem.</div>`;if(p.type==='word'){const words=[...(p.words||[])];if(typeof v4PollVote(p)==='string')words.push(v4PollVote(p));const grouped={};words.forEach(w=>grouped[w]=(grouped[w]||0)+1);return `<div class="v4-results"><h2>Klassens svar</h2><div class="v4-word-results" aria-live="polite">${Object.entries(grouped).map(([w,n])=>`<span>${E(w)}${n>1?' ×'+n:''}</span>`).join('')||'<p class="small muted">Ingen svar endnu.</p>'}</div><p class="small muted">${total} svar · Samlede svar uden elevnavne</p></div>`;}return `<div class="v4-results"><h2>Klassens svar</h2>${p.options.map((o,i)=>`<div class="v4-result-row"><span>${p.type==='mood'?v4Emoji[i]+' ':''}${E(o)}</span><div class="v4-result-track" aria-hidden="true"><span style="width:${total?counts[i]/total*100:0}%"></span></div><strong>${counts[i]}</strong></div>`).join('')}<p class="small muted" aria-live="polite">${total} svar · Samlede svar uden elevnavne</p></div>`;}
function v4PollPage(p,teacher=false,present=false){if(!teacher&&p.course!==U.activeCourse)return `${title('Denne afstemning hører til et andet forløb.')}${v3EmptyLearning()}`;const vote=v4PollVote(p),open=p.status==='open',cn=courseData.find(c=>c.id===p.course).name,controls=teacher?`<div class="v4-poll-controls"><button type="button" class="action" data-v4="poll-status" data-id="${p.id}" data-value="${open?'closed':'open'}">${open?'Luk for svar':p.status==='draft'?'Start afstemning':'Åbn igen'}</button><button type="button" class="secondary" data-v4="poll-results" data-id="${p.id}">${p.showResults?'Skjul resultater for elever':'Vis resultater for elever'}</button>${A('/teacher/polls/'+p.id+(present?'':'/present'),present?'Tilbage til styring':'Vis på tavlen','secondary')}${A('/teacher/polls','Alle afstemninger','secondary')}<button type="button" class="secondary" data-v4="preview-poll" data-id="${p.id}">Prøv elevvisningen</button></div>`:'';return `${present?'<section class="v4-presentation">':''}${present?`<div class="v4-poll-meta">${open?'<span class="v4-live-dot" aria-hidden="true"></span>':''}${open?'Åben for svar':'Lukket'} · ${cn}</div><h1>${E(p.question)}</h1>`:title(p.question,cn+' · '+v4PollNames[p.type])}${controls}${!teacher?`<div class="v4-poll-meta">${pill(open?'Åben nu':'Afsluttet',open?'green':'')}<span>Dit svar vises uden dit navn i klassens resultater.</span></div>${open?p.type==='word'?`<form data-v4-form="vote-word" data-id="${p.id}" style="margin-top:20px"><label class="field">Dit korte svar<input name="answer" maxlength="60" required value="${E(typeof vote==='string'?vote:'')}" placeholder="Et ord eller en kort sætning …"></label><button type="button" class="action" data-v4="vote-word">${vote===undefined?'Send svar':'Opdatér svar'}</button></form>`:`<div class="v4-poll-options ${p.type}">${p.options.map((o,i)=>`<button type="button" class="v4-poll-option" data-v4="vote" data-id="${p.id}" data-index="${i}" aria-pressed="${vote===i}">${p.type==='mood'?`<span class="v4-mood-emoji" aria-hidden="true">${v4Emoji[i]}</span><span>${E(o)}</span>`:p.type==='rating'?E(o):`<span class="v4-choice-key" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${E(o)}</span>`}</button>`).join('')}</div>`:'<div class="callout">Underviseren har lukket runden. Du kan se de frigivne resultater.</div>'}${vote!==undefined?'<div class="v4-poll-receipt" role="status">✓ Dit svar er registreret.</div>':''}`:''}${v4Results(p,teacher)}${!teacher?`<div class="actions">${A('/activities','Tilbage til alle aktiviteter','secondary')}</div>`:''}${present?`<p class="small muted" style="margin-top:22px">Deltag fra Aktiviteter på platformen.</p></section>`:''}`;}
function v4RegisterPoll(p){add('/polls/'+p.id,p.question,'Afstemninger',()=>v4PollPage(p),'activities');add('/teacher/polls/'+p.id,'Styr · '+p.question,'Afstemninger',()=>v4PollPage(p,true),'teacher-polls');add('/teacher/polls/'+p.id+'/present','Tavle · '+p.question,'Tavlevisning',()=>v4PollPage(p,true,true),'teacher-polls');}
