function v4PollManager(){return `${title('Afstemninger til klassen','Start et stemningstjek, stil et spørgsmål, eller saml korte svar på tavlen.')}<div class="actions">${A('/teacher/polls/new','Opret afstemning','action')}<button type="button" class="secondary" data-v4="new-mood">Start nyt stemningstjek</button></div><div class="filters">${['Alle','Aktive','Kladder','Afsluttede'].map(t=>`<button class="filter" data-v4="poll-filter" data-value="${t}" aria-pressed="${W.pollFilter===t}">${t}</button>`).join('')}</div><div class="v4-activity-list">${W.polls.filter(p=>W.pollFilter==='Alle'||p.status===({Aktive:'open',Kladder:'draft',Afsluttede:'closed'})[W.pollFilter]).map(p=>v4PollRow(p,true)).join('')||'<p class="small muted" style="padding:18px 0">Ingen afstemninger i dette udvalg.</p>'}</div>`;}
function v4PollEditor(){return `${title('Opret en afstemning','Et enkelt spørgsmål til klassen. Gem det som kladde, eller start med det samme.')}<section class="panel"><form data-v4-form="poll"><label class="field">Spørgsmål<input name="question" maxlength="150" required placeholder="Hvad vil du spørge klassen om?"></label>${v2Select('Forløb','course',courseData.map(c=>[c.id,c.name]),U.activeCourse||'h3')}<label class="field">Svartype<select name="type" data-v4-change="poll-type">${Object.entries(v4PollNames).map(([v,t])=>`<option value="${v}" ${v==='choice'?'selected':''}>${t}</option>`).join('')}</select></label><label class="field" id="v4-answer-options">Svarmuligheder · én pr. linje<textarea name="options" placeholder="API og requests&#10;Database&#10;Realtime"></textarea><small>Vælg mellem 2 og 6 muligheder. Stemning og skala har faste svar.</small></label><label class="checklabel"><input type="checkbox" name="showResults">Elever må se resultaterne fra start</label><div id="v4-poll-error" role="alert"></div><div class="actions"><button type="button" class="action" data-v4="save-poll" data-start="true">Start afstemning</button><button type="button" class="secondary" data-v4="save-poll" data-start="false">Gem kladde</button></div></form></section>`;}

