add('/universe/shop','Butik','Mit univers',()=>v4Shop(),'universe');
add('/universe/unlocks','Level og badge-oplåsninger','Mit univers',()=>v4Unlocks(),'universe');
for(const i of v4Items)add('/universe/shop/items/'+i.id,i.name,'Butiksvarer',()=>v4ItemPage(i),'universe');
